 11→/**
 12→ * Build a breadcrumb-style path string for a folder by walking up the tree.
 13→ * e.g., "My Vault / Documents / Reports"
 14→ */
 15→function buildFolderPath(folderId: string): string {
 16→  const folders = useFolderStore.getState().folders;
 17→  const parts: string[] = [];
 18→  let currentId: string | null = folderId;
 19→
 20→  while (currentId !== null) {
 21→    const folder: FolderNode | undefined = folders[currentId];
 22→    if (!folder) break;
 23→    // Stop before including the root node (its name is already the "My Vault" prefix)
 24→    if (folder.parentId === null) break;
 25→    parts.unshift(folder.name);
 26→    currentId = folder.parentId;
 27→  }
 28→
 29→  return parts.length > 0 ? `My Vault / ${parts.join(' / ')}` : 'My Vault';
 30→}
 31→
 32→/**
 33→ * Get the parent folder node from the store, resolving 'root' via vault state.
 34→ */
 35→function getParentFolder(parentId: string): FolderNode | null {
 36→  const freshState = useFolderStore.getState();
 37→  return parentId === 'root'
 38→    ? getRootFolderState(useVaultStore.getState(), freshState.folders)
 39→    : freshState.folders[parentId];
 40→}
