  1→import { useCallback } from 'react';
  2→import { useUploadStore } from '../stores/upload.store';
  3→import { useQuotaStore } from '../stores/quota.store';
  4→import { useFolderStore } from '../stores/folder.store';
  5→import { useVaultStore } from '../stores/vault.store';
  6→import { useAuthStore } from '../stores/auth.store';
  7→import { getSdkClient, hasSdkClient, ensureFolderRegistered } from '../lib/sdk-provider';
  8→import { getRootFolderState } from './folder-helpers';
  9→import type { PendingReplacement } from '../stores/upload.store';
 10→
 11→export const MAX_FILE_SIZE = 100 * 1024 * 1024; // 100MB per FILE-01
 12→
 13→/**
 14→ * Check whether a drag event carries external files from the OS (Finder/Explorer)
 15→ * rather than an internal app drag (which sets application/json).
 16→ */
 17→export function isExternalFileDrag(dataTransfer: DataTransfer): boolean {
 18→  return dataTransfer.types.includes('Files') && !dataTransfer.types.includes('application/json');
 19→}
 20→
 21→/**
 22→ * Hook for handling external file drops (from Finder/Explorer) anywhere in the app.
 23→ *
 24→ * Uses the SDK's uploadFile() for atomic encrypt → upload → register flow.
 25→ * All IPNS state is managed by the SDK — no dual-path conflicts.
 26→ */
 27→export function useDropUpload() {
 28→  const uploadStatus = useUploadStore((s) => s.status);
 29→  const isUploading =
 30→    uploadStatus === 'encrypting' || uploadStatus === 'uploading' || uploadStatus === 'registering';
 31→
 32→  const handleFileDrop = useCallback(async (files: File[], folderId: string): Promise<boolean> => {
 33→    // Filter out oversized files
 34→    const oversized = files.filter((f) => f.size > MAX_FILE_SIZE);
 35→    if (oversized.length > 0) {
 36→      useUploadStore
 37→        .getState()
 38→        .setError(`Files exceed 100MB limit: ${oversized.map((f) => f.name).join(', ')}`);
 39→      return false;
 40→    }
 41→
 42→    if (files.length === 0) return false;
 43→
 44→    // Check quota
 45→    const totalSize = files.reduce((sum, f) => sum + f.size, 0);
 46→    const quotaStore = useQuotaStore.getState();
 47→    if (!quotaStore.canUpload(totalSize)) {
 48→      useUploadStore.getState().setError('Not enough storage space for these files');
 49→      return false;
 50→    }
 51→
 52→    // Check for duplicates within batch
 53→    const batchNames = new Set<string>();
 54→    for (const f of files) {
 55→      if (batchNames.has(f.name)) {
 56→        useUploadStore.getState().setError(`Duplicate file name in selection: ${f.name}`);
 57→        return false;
 58→      }
 59→      batchNames.add(f.name);
 60→    }
 61→
 62→    // Identify which files already exist in the target folder
 63→    const folder = useFolderStore.getState().folders[folderId];
 64→    const existingByName = new Map<string, string>(); // name → fileId
 65→    const existingFolderNames = new Set<string>();
 66→    if (folder) {
 67→      for (const child of folder.children) {
 68→        if (child.type === 'file') {
 69→          existingByName.set(child.name, child.id);
 70→        } else if (child.type === 'folder') {
 71→          existingFolderNames.add(child.name);
 72→        }
 73→      }
 74→    }
 75→
 76→    // Fail fast on file–folder name collisions
 77→    const folderNameConflicts = files.filter((f) => existingFolderNames.has(f.name));
 78→    if (folderNameConflicts.length > 0) {
 79→      useUploadStore
 80→        .getState()
 81→        .setError(
 82→          `Cannot upload file(s) with the same name as an existing folder: ${folderNameConflicts.map((f) => f.name).join(', ')}`
 83→        );
 84→      return false;
 85→    }
 86→
 87→    const newFiles = files.filter((f) => !existingByName.has(f.name));
 88→    const duplicateFiles = files.filter((f) => existingByName.has(f.name));
 89→
 90→    if (!hasSdkClient()) {
 91→      useUploadStore.getState().setError('SDK not initialized — please log in again');
 92→      return false;
 93→    }
 94→
 95→    const client = getSdkClient();
 96→
 97→    // Resolve parent folder and ensure it's registered in the SDK
 98→    const folders = useFolderStore.getState().folders;
 99→    const vault = useVaultStore.getState();
100→    const parentFolder =
101→      folderId === 'root' ? getRootFolderState(vault, folders) : folders[folderId];
102→    if (!parentFolder) {
103→      useUploadStore.getState().setError('Parent folder not found');
104→      return false;
105→    }
106→    ensureFolderRegistered(parentFolder);
107→
108→    const uploadStore = useUploadStore.getState();
109→    // Start with all files (new + duplicates) since we encrypt all upfront
110→    uploadStore.startUpload(files.length);
111→
112→    const uploadedCids: string[] = []; // Track for cleanup on failure
113→
114→    try {
115→      // Upload new files via SDK (atomic: encrypt → IPFS → FilePointer → IPNS publish)
116→      for (const file of newFiles) {
117→        if (useUploadStore.getState().status === 'cancelled') {
118→          throw new Error('Upload cancelled by user');
119→        }
120→
121→        useUploadStore.getState().setUploading(file.name, 0);
122→
123→        // Read File to Uint8Array
124→        const data = new Uint8Array(await file.arrayBuffer());
125→
126→        const result = await client.uploadFile(
127→          parentFolder.ipnsName,
128→          data,
129→          file.name,
130→          file.type || 'application/octet-stream',
131→          (percent) => useUploadStore.getState().setUploading(file.name, percent)
132→        );
133→
134→        uploadedCids.push(result.cid);
135→        useUploadStore.getState().fileComplete();
136→      }
137→
138→      // Handle duplicate files: encrypt + upload to IPFS, then surface as pending replacements
139→      // (These don't get registered in the folder — the user decides via the Replace dialog)
140→      // Duplicate files always upload to CipherBox relay (not BYO node) because
141→      // they're staged for the replacement dialog. Once the user confirms, the
142→      // replacement flow uses SDK's uploadFile() which respects pinning mode.
143→      if (duplicateFiles.length > 0) {
144→        const replacements: PendingReplacement[] = [];
145→
146→        // Hoist dynamic imports before the loop to avoid per-iteration async overhead
147→        const { encryptFile } = await import('../services/file-crypto.service');
148→        const { addToIpfs } = await import('../lib/api/ipfs');
149→
150→        for (const file of duplicateFiles) {
151→          if (useUploadStore.getState().status === 'cancelled') {
152→            throw new Error('Upload cancelled by user');
153→          }
154→
155→          useUploadStore.getState().setUploading(file.name, 0);
156→
157→          // For duplicates, we only encrypt + upload to IPFS (don't register in folder)
158→          // Use the old upload service for this since SDK's uploadFile registers in folder
159→          const userPublicKey = useAuthStore.getState().vaultKeypair?.publicKey;
160→          if (!userPublicKey) throw new Error('No keypair available');
161→          const encrypted = await encryptFile(file, userPublicKey);
162→          // Pass a clean Uint8Array copy — never use .buffer (may include extra bytes)
163→          const blob = new Blob([new Uint8Array(encrypted.ciphertext)], {
164→            type: 'application/octet-stream',
165→          });
166→          const ipfsResult = await addToIpfs(blob, (percent) =>
167→            useUploadStore.getState().setUploading(file.name, percent)
168→          );
169→
170→          uploadedCids.push(ipfsResult.cid);
171→          useUploadStore.getState().fileComplete();
172→
173→          const existingFileId = existingByName.get(file.name);
174→          if (existingFileId) {
175→            replacements.push({
176→              fileName: file.name,
177→              fileId: existingFileId,
178→              parentId: folderId,
179→              encryptedData: {
180→                cid: ipfsResult.cid,
181→                wrappedKey: encrypted.wrappedKey,
182→                iv: encrypted.iv,
183→                size: file.size,
184→                encryptionMode: encrypted.encryptionMode,
185→              },
186→            });
187→          }
188→        }
189→
190→        if (replacements.length > 0) {
191→          useUploadStore.getState().setPendingReplacements(replacements);
192→        }
193→      }
194→
195→      useUploadStore.getState().setSuccess();
196→      return true;
197→    } catch (err) {
198→      const message = (err as Error).message;
199→      if (message !== 'Upload cancelled by user') {
200→        useUploadStore.getState().setError(message);
201→      }
202→      // Best-effort cleanup: unpin orphaned CIDs from failed upload
203→      if (uploadedCids.length > 0) {
204→        import('../lib/api/ipfs')
205→          .then(({ unpinFromIpfs }) => {
206→            for (const cid of uploadedCids) {
207→              unpinFromIpfs(cid).catch(() => {});
208→            }
209→          })
210→          .catch(() => {});
211→      }
212→      return false;
213→    } finally {
214→      // Refresh quota from server
215→      await useQuotaStore.getState().fetchQuota();
216→    }
217→  }, []);
218→
219→  return { handleFileDrop, isUploading };
220→}
