 1→/**
 2→ * @cipherbox/core - Per-File Metadata Types
 3→ *
 4→ * Type definitions for per-file IPNS metadata records.
 5→ * Each file gets its own IPNS record containing encrypted metadata,
 6→ * while the parent folder only stores a slim FilePointer reference.
 7→ */
 8→
 9→/** A single past version of a file. Stores full crypto context for independent decryption. */
10→export type VersionEntry = {
11→  /** IPFS CID of the encrypted file content for this version */
12→  cid: string;
13→  /** Hex-encoded ECIES-wrapped AES-256 key for decrypting this version */
14→  fileKeyEncrypted: string;
15→  /** Hex-encoded IV used for this version's encryption */
16→  fileIv: string;
17→  /** Original file size in bytes (before encryption) */
18→  size: number;
19→  /** When this version was created (Unix ms) -- i.e., when it became a "past" version */
20→  timestamp: number;
21→  /** Encryption mode used for this version */
22→  encryptionMode: 'GCM' | 'CTR';
23→};
24→
25→/**
26→ * Decrypted per-file metadata structure.
27→ * Stored as an encrypted blob in the file's own IPNS record.
28→ * Encrypted with the parent folder's folderKey (NOT the file's own key).
29→ */
30→export type FileMetadata = {
31→  /** Schema version */
32→  version: 'v1';
33→  /** IPFS CID of the encrypted file content */
34→  cid: string;
35→  /** Hex-encoded ECIES-wrapped AES-256 key for decrypting file */
36→  fileKeyEncrypted: string;
37→  /** Hex-encoded IV used for file encryption */
38→  fileIv: string;
39→  /** Original file size in bytes (before encryption) */
40→  size: number;
41→  /** MIME type of the original file */
42→  mimeType: string;
43→  /** Encryption mode (optional for backward compat; defaults to 'GCM') */
44→  encryptionMode?: 'GCM' | 'CTR';
45→  /** Creation timestamp (Unix ms) */
46→  createdAt: number;
47→  /** Last modification timestamp (Unix ms) */
48→  modifiedAt: number;
49→  /** Past versions of this file (newest first). Omitted if no versions exist. */
50→  versions?: VersionEntry[];
51→};
52→
53→/**
54→ * Slim file reference stored in v2 folder metadata.
55→ * Points to a file's own IPNS record instead of embedding all file data inline.
56→ */
57→export type FilePointer = {
58→  type: 'file';
59→  /** UUID for internal reference */
60→  id: string;
61→  /** File name (plaintext, since folder metadata is encrypted) */
62→  name: string;
63→  /** IPNS name of the file's own metadata record */
64→  fileMetaIpnsName: string;
65→  /** Hex-encoded ECIES-wrapped Ed25519 private key for signing this file's IPNS record.
66→   *  Present for files created after the random-key migration. Absent for legacy files
67→   *  whose IPNS key is derived deterministically via HKDF. */
68→  ipnsPrivateKeyEncrypted?: string;
69→  /** Creation timestamp (Unix ms) */
70→  createdAt: number;
71→  /** Last modification timestamp (Unix ms) */
72→  modifiedAt: number;
73→};
74→
75→/**
76→ * Encrypted file metadata for storage/transmission.
77→ * Same format as EncryptedFolderMetadata (hex IV + base64 ciphertext).
78→ */
79→export type EncryptedFileMetadata = {
80→  /** Hex-encoded 12-byte IV for AES-GCM */
81→  iv: string;
82→  /** Base64-encoded AES-GCM ciphertext (includes 16-byte auth tag) */
83→  data: string;
84→};
85→

  1→/**
  2→ * @cipherbox/core - File Metadata Encryption
  3→ *
  4→ * Encrypts and decrypts per-file metadata using AES-256-GCM.
  5→ * File metadata is encrypted with the parent folder's folderKey
  6→ * (NOT the file's own encryption key).
  7→ */
  8→
  9→import {
 10→  encryptAesGcm,
 11→  decryptAesGcm,
 12→  generateIv,
 13→  bytesToHex,
 14→  hexToBytes,
 15→  CryptoError,
 16→} from '@cipherbox/crypto';
 17→import type { FileMetadata, EncryptedFileMetadata, VersionEntry } from './types';
 18→
 19→/**
 20→ * [SECURITY: MEDIUM-08] Chunk-based base64 encoding to avoid call stack issues
 21→ * with large Uint8Arrays (spread operator has argument limits ~65536)
 22→ */
 23→function uint8ArrayToBase64(bytes: Uint8Array): string {
 24→  const CHUNK_SIZE = 32768;
 25→  let result = '';
 26→  for (let i = 0; i < bytes.length; i += CHUNK_SIZE) {
 27→    const chunk = bytes.subarray(i, Math.min(i + CHUNK_SIZE, bytes.length));
 28→    result += String.fromCharCode(...chunk);
 29→  }
 30→  return btoa(result);
 31→}
 32→
 33→/**
 34→ * Validates a single version entry from the versions array.
 35→ * All fields are required (versions always have explicit encryption mode).
 36→ */
 37→function validateVersionEntry(entry: unknown, index: number): VersionEntry {
 38→  if (typeof entry !== 'object' || entry === null) {
 39→    throw new CryptoError(
 40→      `Invalid file metadata format: versions[${index}] is not an object`,
 41→      'DECRYPTION_FAILED'
 42→    );
 43→  }
 44→
 45→  const obj = entry as Record<string, unknown>;
 46→
 47→  if (typeof obj.cid !== 'string') {
 48→    throw new CryptoError(
 49→      `Invalid file metadata format: versions[${index}].cid must be string`,
 50→      'DECRYPTION_FAILED'
 51→    );
 52→  }
 53→  if (typeof obj.fileKeyEncrypted !== 'string') {
 54→    throw new CryptoError(
 55→      `Invalid file metadata format: versions[${index}].fileKeyEncrypted must be string`,
 56→      'DECRYPTION_FAILED'
 57→    );
 58→  }
 59→  if (typeof obj.fileIv !== 'string') {
 60→    throw new CryptoError(
 61→      `Invalid file metadata format: versions[${index}].fileIv must be string`,
 62→      'DECRYPTION_FAILED'
 63→    );
 64→  }
 65→  if (typeof obj.size !== 'number') {
 66→    throw new CryptoError(
 67→      `Invalid file metadata format: versions[${index}].size must be number`,
 68→      'DECRYPTION_FAILED'
 69→    );
 70→  }
 71→  if (typeof obj.timestamp !== 'number') {
 72→    throw new CryptoError(
 73→      `Invalid file metadata format: versions[${index}].timestamp must be number`,
 74→      'DECRYPTION_FAILED'
 75→    );
 76→  }
 77→  if (obj.encryptionMode !== 'GCM' && obj.encryptionMode !== 'CTR') {
 78→    throw new CryptoError(
 79→      `Invalid file metadata format: versions[${index}].encryptionMode must be GCM or CTR`,
 80→      'DECRYPTION_FAILED'
 81→    );
 82→  }
 83→
 84→  return {
 85→    cid: obj.cid as string,
 86→    fileKeyEncrypted: obj.fileKeyEncrypted as string,
 87→    fileIv: obj.fileIv as string,
 88→    size: obj.size as number,
 89→    timestamp: obj.timestamp as number,
 90→    encryptionMode: obj.encryptionMode as 'GCM' | 'CTR',
 91→  };
 92→}
 93→
 94→/**
 95→ * [SECURITY: MEDIUM-07] Runtime validation for decrypted file metadata.
 96→ * Ensures the decrypted data conforms to the expected FileMetadata schema.
 97→ */
 98→export function validateFileMetadata(data: unknown): FileMetadata {
 99→  if (typeof data !== 'object' || data === null) {
100→    throw new CryptoError('Invalid file metadata format: not an object', 'DECRYPTION_FAILED');
101→  }
102→
103→  const obj = data as Record<string, unknown>;
104→
105→  // Validate version field
106→  if (obj.version !== 'v1') {
107→    throw new CryptoError('Invalid file metadata format: unsupported version', 'DECRYPTION_FAILED');
108→  }
109→
110→  // Validate required string fields
111→  if (typeof obj.cid !== 'string') {
112→    throw new CryptoError('Invalid file metadata format: cid must be string', 'DECRYPTION_FAILED');
113→  }
114→  if (typeof obj.fileKeyEncrypted !== 'string') {
115→    throw new CryptoError(
116→      'Invalid file metadata format: fileKeyEncrypted must be string',
117→      'DECRYPTION_FAILED'
118→    );
119→  }
120→  if (typeof obj.fileIv !== 'string') {
121→    throw new CryptoError(
122→      'Invalid file metadata format: fileIv must be string',
123→      'DECRYPTION_FAILED'
124→    );
125→  }
126→  if (typeof obj.mimeType !== 'string') {
127→    throw new CryptoError(
128→      'Invalid file metadata format: mimeType must be string',
129→      'DECRYPTION_FAILED'
130→    );
131→  }
132→
133→  // Validate required number fields
134→  if (typeof obj.size !== 'number') {
135→    throw new CryptoError('Invalid file metadata format: size must be number', 'DECRYPTION_FAILED');
136→  }
137→  if (typeof obj.createdAt !== 'number') {
138→    throw new CryptoError(
139→      'Invalid file metadata format: createdAt must be number',
140→      'DECRYPTION_FAILED'
141→    );
142→  }
143→  if (typeof obj.modifiedAt !== 'number') {
144→    throw new CryptoError(
145→      'Invalid file metadata format: modifiedAt must be number',
146→      'DECRYPTION_FAILED'
147→    );
148→  }
149→
150→  // Validate optional encryptionMode: if present must be 'GCM' or 'CTR'; if absent default to 'GCM'
151→  if (obj.encryptionMode !== undefined) {
152→    if (obj.encryptionMode !== 'GCM' && obj.encryptionMode !== 'CTR') {
153→      throw new CryptoError(
154→        'Invalid file metadata format: encryptionMode must be GCM or CTR',
155→        'DECRYPTION_FAILED'
156→      );
157→    }
158→  }
159→
160→  // Validate optional versions array
161→  let validatedVersions: VersionEntry[] | undefined;
162→  if (obj.versions !== undefined) {
163→    if (!Array.isArray(obj.versions)) {
164→      throw new CryptoError(
165→        'Invalid file metadata format: versions must be an array',
166→        'DECRYPTION_FAILED'
167→      );
168→    }
169→    if (obj.versions.length > 0) {
170→      validatedVersions = obj.versions.map((entry: unknown, i: number) =>
171→        validateVersionEntry(entry, i)
172→      );
173→    }
174→  }
175→
176→  const result: FileMetadata = {
177→    version: 'v1',
178→    cid: obj.cid as string,
179→    fileKeyEncrypted: obj.fileKeyEncrypted as string,
180→    fileIv: obj.fileIv as string,
181→    size: obj.size as number,
182→    mimeType: obj.mimeType as string,
183→    encryptionMode: (obj.encryptionMode as 'GCM' | 'CTR' | undefined) ?? 'GCM',
184→    createdAt: obj.createdAt as number,
185→    modifiedAt: obj.modifiedAt as number,
186→  };
187→
188→  if (validatedVersions) {
189→    result.versions = validatedVersions;
190→  }
191→
192→  return result;
193→}
194→
195→/**
196→ * Encrypts file metadata with AES-256-GCM using the parent folder's key.
197→ *
198→ * @param metadata - Plaintext file metadata object
199→ * @param folderKey - 32-byte AES key of the parent folder
200→ * @returns Encrypted metadata with IV (hex) and ciphertext (base64)
201→ */
202→export async function encryptFileMetadata(
203→  metadata: FileMetadata,
204→  folderKey: Uint8Array
205→): Promise<EncryptedFileMetadata> {
206→  // Generate random IV for this encryption
207→  const iv = generateIv();
208→
209→  // Serialize metadata to JSON bytes
210→  const plaintext = new TextEncoder().encode(JSON.stringify(metadata));
211→
212→  // Encrypt with AES-256-GCM
213→  const ciphertext = await encryptAesGcm(plaintext, folderKey, iv);
214→
215→  // Encode for storage
216→  // [SECURITY: MEDIUM-08] Use chunked base64 encoding for large metadata
217→  return {
218→    iv: bytesToHex(iv),
219→    data: uint8ArrayToBase64(ciphertext),
220→  };
221→}
222→
223→/**
224→ * Decrypts file metadata encrypted with AES-256-GCM.
225→ *
226→ * @param encrypted - Encrypted metadata with IV (hex) and ciphertext (base64)
227→ * @param folderKey - 32-byte AES key of the parent folder
228→ * @returns Decrypted file metadata object
229→ * @throws CryptoError if decryption fails (wrong key, corrupted data, etc.)
230→ */
231→export async function decryptFileMetadata(
232→  encrypted: EncryptedFileMetadata,
233→  folderKey: Uint8Array
234→): Promise<FileMetadata> {
235→  // Decode IV and ciphertext
236→  const iv = hexToBytes(encrypted.iv);
237→  const ciphertext = Uint8Array.from(atob(encrypted.data), (c) => c.charCodeAt(0));
238→
239→  // Decrypt with AES-256-GCM
240→  const plaintext = await decryptAesGcm(ciphertext, folderKey, iv);
241→
242→  // Parse JSON back to metadata object
243→  // [SECURITY: MEDIUM-07] Validate the decrypted data before returning
244→  let parsed: unknown;
245→  try {
246→    parsed = JSON.parse(new TextDecoder().decode(plaintext));
247→  } catch {
248→    throw new CryptoError('Invalid file metadata format: not valid JSON', 'DECRYPTION_FAILED');
249→  }
250→  return validateFileMetadata(parsed);
251→}
