 86→/**
 87→ * Create a new subfolder with generated keys.
 88→ *
 89→ * Generates new Ed25519 IPNS keypair and AES-256 folder key,
 90→ * wraps them with the user's public key for storage.
 91→ *
 92→ * @returns Created folder entry and decrypted keys
 93→ */
 94→export async function createSubfolder(params: {
 95→  name: string;
 96→  userPublicKey: Uint8Array;
 97→  teeKeys?: TeeKeys;
 98→}): Promise<{
 99→  folder: FolderEntry;
100→  ipnsPrivateKey: Uint8Array;
101→  folderKey: Uint8Array;
102→  encryptedIpnsPrivateKey?: string;
103→  keyEpoch?: number;
104→}> {
105→  // 1. Generate Ed25519 keypair for folder IPNS
106→  const ipnsKeypair = await generateEd25519Keypair();
107→  const ipnsName = await deriveIpnsName(ipnsKeypair.publicKey);
108→
109→  // 2. Generate random AES-256 folder key
110→  const folderKey = generateRandomBytes(32);
111→
112→  // 3. Wrap keys with user's public key (ECIES encryption)
113→  const ipnsPrivateKeyEncrypted = bytesToHex(
114→    await wrapKey(ipnsKeypair.privateKey, params.userPublicKey)
115→  );
116→  const folderKeyEncrypted = bytesToHex(await wrapKey(folderKey, params.userPublicKey));
117→
118→  // 4. TEE-02: Encrypt IPNS private key with TEE public key for republishing.
119→  //    Wrap remaining steps in try/catch to zero key material on error.
120→  //    On success the caller receives the keys, so we only zero on failure.
121→  try {
122→    let encryptedIpnsPrivateKey: string | undefined;
123→    let keyEpoch: number | undefined;
124→
125→    if (params.teeKeys?.currentPublicKey) {
126→      const teePublicKey = hexToBytes(params.teeKeys.currentPublicKey);
127→      const encryptedKey = await wrapKey(ipnsKeypair.privateKey, teePublicKey);
128→      encryptedIpnsPrivateKey = bytesToHex(encryptedKey);
129→      keyEpoch = params.teeKeys.currentEpoch;
130→    }
131→
132→    // 5. Create folder entry for parent's metadata
133→    const now = Date.now();
134→    const folder: FolderEntry = {
135→      type: 'folder',
136→      id: crypto.randomUUID(),
137→      name: params.name,
138→      ipnsName,
139→      ipnsPrivateKeyEncrypted,
140→      folderKeyEncrypted,
141→      createdAt: now,
142→      modifiedAt: now,
143→    };
144→
145→    return {
146→      folder,
147→      ipnsPrivateKey: ipnsKeypair.privateKey,
148→      folderKey,
149→      encryptedIpnsPrivateKey,
150→      keyEpoch,
151→    };
152→  } catch (error) {
153→    ipnsKeypair.privateKey.fill(0);
154→    folderKey.fill(0);
155→    throw error;
156→  }
157→}
158→
159→/**
160→ * Update folder metadata and publish to IPNS.
161→ *
162→ * Encrypts the metadata with the folder key, uploads to IPFS,
163→ * and publishes an updated IPNS record pointing to the new CID.
164→ *
165→ * @returns New CID and sequence number
166→ */
167→export async function updateFolderMetadataAndPublish(params: {
168→  children: FolderChild[];
169→  folderKey: Uint8Array;
170→  ipnsPrivateKey: Uint8Array;
171→  ipnsName: string;
172→  sequenceNumber: bigint;
173→  ctx: SdkContext;
174→  encryptedIpnsPrivateKey?: string;
175→  keyEpoch?: number;
176→}): Promise<{ cid: string; newSequenceNumber: bigint }> {
177→  return withPerf('folder:update-publish', async () => {
178→    // 1. Create v2 folder metadata
179→    const metadata: FolderMetadata = {
180→      version: 'v2',
181→      children: params.children,
182→    };
183→
184→    // 2. Encrypt metadata with folder key
185→    const encrypted = await encryptFolderMetadata(metadata, params.folderKey);
186→
187→    // 3. Upload to IPFS via backend relay
188→    const jsonStr = JSON.stringify(encrypted);
189→    const encryptedBytes = new TextEncoder().encode(jsonStr);
190→    const { cid } = await addToIpfs(params.ctx, encryptedBytes);
191→
192→    // 4. Publish IPNS record with conflict retry
193→    //    On 409, resolve current seq from IPNS and retry once
194→    let currentSeq = params.sequenceNumber;
195→
196→    for (let attempt = 0; attempt < 2; attempt++) {
197→      const newSeq = currentSeq + 1n;
198→      try {
199→        await createAndPublishIpnsRecord({
200→          ipnsPrivateKey: params.ipnsPrivateKey,
201→          ipnsName: params.ipnsName,
202→          metadataCid: cid,
203→          sequenceNumber: newSeq,
204→          encryptedIpnsPrivateKey: params.encryptedIpnsPrivateKey,
205→          keyEpoch: params.keyEpoch,
206→          expectedSequenceNumber: currentSeq.toString(),
207→          ctx: params.ctx,
208→        });
209→        return { cid, newSequenceNumber: newSeq };
210→      } catch (err) {
211→        const is409 =
212→          (err as Error & { status?: number }).status === 409 ||
213→          (err as Error & { response?: { status?: number } }).response?.status === 409;
214→        if (!is409 || attempt > 0) throw err;
215→
216→        // Re-sync: resolve current seq from IPNS
217→        const resolved = await resolveIpnsRecord(params.ipnsName, params.ctx);
218→        if (resolved) {
219→          currentSeq = resolved.sequenceNumber;
220→        } else {
221→          throw err; // Can't resolve → give up
222→        }
223→      }
224→    }
225→
226→    // Should not reach here, but TypeScript needs it
227→    throw new Error('Publish failed after retry');
228→  });
229→}
