277→/**
278→ * Add a file pointer to folder children.
279→ *
280→ * Pure metadata operation: returns updated children array with the new file pointer.
281→ */
282→export function addFilePointerToFolder(params: {
283→  children: FolderChild[];
284→  fileId: string;
285→  fileName: string;
286→  fileMetaIpnsName: string;
287→  ipnsPrivateKeyEncrypted: string;
288→}): { updatedChildren: FolderChild[]; filePointer: FilePointer } {
289→  const nameExists = params.children.some((c) => c.name === params.fileName);
290→  if (nameExists) throw new Error('A file with this name already exists');
291→
292→  const now = Date.now();
293→  const filePointer: FilePointer = {
294→    type: 'file',
295→    id: params.fileId,
296→    name: params.fileName,
297→    fileMetaIpnsName: params.fileMetaIpnsName,
298→    ipnsPrivateKeyEncrypted: params.ipnsPrivateKeyEncrypted,
299→    createdAt: now,
300→    modifiedAt: now,
301→  };
302→
303→  return {
304→    updatedChildren: [...params.children, filePointer],
305→    filePointer,
306→  };
307→}
