309→/**
310→ * Move a child entry between folders.
311→ *
312→ * Pure metadata operation: returns updated source and dest children arrays.
313→ * Uses add-before-remove pattern conceptually (caller publishes dest first, then source).
314→ */
315→export function moveItem(params: {
316→  sourceChildren: FolderChild[];
317→  destChildren: FolderChild[];
318→  childId: string;
319→}): {
320→  updatedSourceChildren: FolderChild[];
321→  updatedDestChildren: FolderChild[];
322→  movedItem: FolderChild;
323→} {
324→  const index = params.sourceChildren.findIndex((c) => c.id === params.childId);
325→  if (index === -1) throw new Error('Item not found');
326→
327→  const movedItem = {
328→    ...params.sourceChildren[index],
329→    modifiedAt: Date.now(),
330→  };
331→
332→  // Check name collision in destination
333→  const nameExists = params.destChildren.some((c) => c.name === movedItem.name);
334→  if (nameExists) {
335→    throw new Error('An item with this name already exists in destination');
336→  }
337→
338→  const updatedSourceChildren = params.sourceChildren.filter((c) => c.id !== params.childId);
339→  const updatedDestChildren = [...params.destChildren, movedItem];
340→
341→  return { updatedSourceChildren, updatedDestChildren, movedItem };
342→}
