useEffect(() => {
  if (!open || !item) {
    setContent('');
    setOriginalContent('');
    setError(null);
    setLoading(false);
    setSaving(false);
    return;
  }

  if (!folderKey) {
    setLoading(false);
    setError('Folder key not available');
    return;
  }

  if (!item.fileMetaIpnsName) {
    setLoading(false);
    setError('File metadata IPNS name not available (legacy v1 file?)');
