    description: 'Array of re-wrapped keys to add to the share',
    type: [ShareKeyEntryDto],
  })
  @IsArray()
  @ValidateNested({ each: true })
  @Type(() => ShareKeyEntryDto)
  keys!: ShareKeyEntryDto[];
}

