  1→/**
  2→ * Share Operations Tests
  3→ *
  4→ * Tests sharing a folder between two accounts (Alice and Bob),
  5→ * verifying ECIES key wrapping, re-wrap on mutation, and revocation.
  6→ * Uses multi-account fixture with serial API-client switching.
  7→ */
  8→
  9→import { describe, it, expect, beforeAll, afterAll } from 'vitest';
 10→import { wrapKey, unwrapKey, bytesToHex, hexToBytes } from '@cipherbox/crypto';
 11→import { createMultiAccountFixture, type MultiAccountFixture } from '../fixtures/multi-account';
 12→import { API_URL, testFetch } from '../fixtures/test-harness';
 13→import { generateTextContent } from '../helpers/data-generators';
 14→
 15→describe('Share Operations', () => {
 16→  let fixture: MultiAccountFixture;
 17→
 18→  beforeAll(async () => {
 19→    fixture = await createMultiAccountFixture(['alice', 'bob']);
 20→  });
 21→
 22→  afterAll(async () => {
 23→    if (fixture) await fixture.cleanupAll();
 24→  });
 25→
 26→  let shareId: string;
 27→
 28→  it('should create a share from Alice to Bob', async () => {
 29→    const alice = fixture.accounts.get('alice')!;
 30→    const bob = fixture.accounts.get('bob')!;
 31→
 32→    // Alice creates a folder to share
 33→    const folder = await alice.client.createFolder(alice.rootIpnsName, 'SharedFolder');
 34→    expect(folder.id).toBeTruthy();
 35→
 36→    // Upload a file into the shared folder
 37→    alice.client.registerFolder(
 38→      folder.ipnsName,
 39→      folder.folderKey,
 40→      { publicKey: new Uint8Array(0), privateKey: folder.ipnsPrivateKey },
 41→      [],
 42→      1n
 43→    );
 44→    await alice.client.uploadFile(
 45→      folder.ipnsName,
 46→      generateTextContent('shared content'),
 47→      'shared.txt',
 48→      'text/plain'
 49→    );
 50→
 51→    // Wrap the folder key for Bob using ECIES
 52→    const encryptedKey = await wrapKey(folder.folderKey, bob.publicKey);
 53→
 54→    // Create share via API
 55→    const res = await testFetch(`${API_URL}/shares`, {
 56→      method: 'POST',
 57→      headers: {
 58→        Authorization: `Bearer ${alice.accessToken}`,
 59→        'Content-Type': 'application/json',
 60→      },
 61→      body: JSON.stringify({
 62→        recipientPublicKey: '0x' + bytesToHex(bob.publicKey),
 63→        itemType: 'folder',
 64→        ipnsName: folder.ipnsName,
 65→        itemName: 'SharedFolder',
 66→        encryptedKey: bytesToHex(encryptedKey),
 67→      }),
 68→    });
 69→
 70→    expect(res.status).toBe(201);
 71→    const data = await res.json();
 72→    expect(data.shareId).toBeTruthy();
 73→    shareId = data.shareId;
 74→  });
 75→
 76→  it('should appear in Bob received shares', async () => {
 77→    const bob = fixture.accounts.get('bob')!;
 78→
 79→    const res = await testFetch(`${API_URL}/shares/received`, {
 80→      headers: { Authorization: `Bearer ${bob.accessToken}` },
 81→    });
 82→    expect(res.ok).toBe(true);
 83→
 84→    const data = await res.json();
 85→    expect(data.shares.length).toBeGreaterThanOrEqual(1);
 86→    const share = data.shares.find((s: any) => s.shareId === shareId);
 87→    expect(share).toBeTruthy();
 88→    expect(share.itemName).toBe('SharedFolder');
 89→    expect(share.itemType).toBe('folder');
 90→  });
 91→
 92→  it('should appear in Alice sent shares', async () => {
 93→    const alice = fixture.accounts.get('alice')!;
 94→
 95→    const res = await testFetch(`${API_URL}/shares/sent`, {
 96→      headers: { Authorization: `Bearer ${alice.accessToken}` },
 97→    });
 98→    expect(res.ok).toBe(true);
 99→
100→    const data = await res.json();
101→    const share = data.shares.find((s: any) => s.shareId === shareId);
102→    expect(share).toBeTruthy();
103→  });
104→
105→  it('should allow Bob to unwrap the shared key', async () => {
106→    const bob = fixture.accounts.get('bob')!;
107→
108→    const res = await testFetch(`${API_URL}/shares/received`, {
109→      headers: { Authorization: `Bearer ${bob.accessToken}` },
110→    });
111→    const data = await res.json();
112→    const share = data.shares.find((s: any) => s.shareId === shareId);
113→
114→    // Bob unwraps the key with his private key (API returns hex-encoded ciphertext)
115→    const folderKey = await unwrapKey(hexToBytes(share.encryptedKey), bob.privateKey);
116→    expect(folderKey.length).toBe(32); // AES-256 key
117→  });
118→
119→  it('should reject self-sharing', async () => {
120→    const alice = fixture.accounts.get('alice')!;
121→
122→    const res = await testFetch(`${API_URL}/shares`, {
123→      method: 'POST',
124→      headers: {
125→        Authorization: `Bearer ${alice.accessToken}`,
126→        'Content-Type': 'application/json',
127→      },
128→      body: JSON.stringify({
129→        recipientPublicKey: '0x' + bytesToHex(alice.publicKey),
130→        itemType: 'folder',
131→        ipnsName: alice.rootIpnsName,
132→        itemName: 'SelfShare',
133→        encryptedKey: bytesToHex(new Uint8Array(64)),
134→      }),
135→    });
136→
137→    expect(res.status).toBe(409);
138→  });
139→
140→  it('should revoke the share', async () => {
141→    const alice = fixture.accounts.get('alice')!;
142→
143→    const res = await testFetch(`${API_URL}/shares/${shareId}`, {
144→      method: 'DELETE',
145→      headers: { Authorization: `Bearer ${alice.accessToken}` },
146→    });
147→
148→    expect(res.status).toBe(204);
149→  });
150→
151→  it('should not appear in Bob received shares after revocation', async () => {
152→    const bob = fixture.accounts.get('bob')!;
153→
154→    const res = await testFetch(`${API_URL}/shares/received`, {
155→      headers: { Authorization: `Bearer ${bob.accessToken}` },
156→    });
157→    const data = await res.json();
158→    const share = data.shares.find((s: any) => s.shareId === shareId);
159→    // Revoked shares should not appear in received list
160→    expect(share).toBeUndefined();
161→  });
162→});
