 1→/**
 2→ * Multi-Account Test Fixture
 3→ *
 4→ * Creates N test accounts for tests that require interaction between users
 5→ * (sharing, invite links). Each CipherBoxClient owns its own axios instance,
 6→ * so no singleton switching is needed.
 7→ */
 8→
 9→import { createTestContext, deleteTestAccount, type TestContext } from './test-harness';
10→
11→export interface MultiAccountFixture {
12→  /** All created test contexts, indexed by label */
13→  accounts: Map<string, TestContext>;
14→  /** Destroy all clients and delete all accounts */
15→  cleanupAll: () => Promise<void>;
16→}
17→
18→/**
19→ * Create N test accounts with the given labels.
20→ *
21→ * @example
22→ * const fixture = await createMultiAccountFixture(['alice', 'bob']);
23→ * const alice = fixture.accounts.get('alice')!;
24→ * const bob = fixture.accounts.get('bob')!;
25→ */
26→export async function createMultiAccountFixture(labels: string[]): Promise<MultiAccountFixture> {
27→  const accounts = new Map<string, TestContext>();
28→
29→  // Create accounts sequentially to avoid race conditions on vault init
30→  for (const label of labels) {
31→    const ctx = await createTestContext(label);
32→    accounts.set(label, ctx);
33→  }
34→
35→  const cleanupAll = async (): Promise<void> => {
36→    for (const [, ctx] of accounts) {
37→      ctx.cleanup();
38→      await deleteTestAccount(ctx);
39→    }
40→    accounts.clear();
41→  };
42→
43→  return { accounts, cleanupAll };
44→}
