    for (const client of activeClients) {
      try {
        await deleteAccount(client);
        console.log(`  [C${client.id}] Account deleted`);
      } catch (err) {
        console.warn(
          `  [C${client.id}] Account deletion failed: ${(err as Error).message.slice(0, 100)}`
        );
      }
    }
  });
});

