  1→import {
  2→  Injectable,
  3→  NotFoundException,
  4→  ForbiddenException,
  5→  ConflictException,
  6→  BadRequestException,
  7→} from '@nestjs/common';
  8→import { InjectRepository } from '@nestjs/typeorm';
  9→import { Repository, IsNull, Not } from 'typeorm';
 10→import { Share } from './entities/share.entity';
 11→import { ShareKey } from './entities/share-key.entity';
 12→import { User } from '../auth/entities/user.entity';
 13→import { CreateShareDto } from './dto/create-share.dto';
 14→import { AddShareKeysDto } from './dto/share-key.dto';
 15→
 16→@Injectable()
 17→export class SharesService {
 18→  constructor(
 19→    @InjectRepository(Share)
 20→    private readonly shareRepo: Repository<Share>,
 21→    @InjectRepository(ShareKey)
 22→    private readonly shareKeyRepo: Repository<ShareKey>,
 23→    @InjectRepository(User)
 24→    private readonly userRepo: Repository<User>
 25→  ) {}
 26→
 27→  /**
 28→   * Create a new share record with re-wrapped keys.
 29→   * Validates recipient exists and is not the sharer.
 30→   * Prevents duplicate active shares for the same item/recipient pair.
 31→   */
 32→  async createShare(sharerId: string, dto: CreateShareDto): Promise<Share> {
 33→    // Look up recipient by publicKey
 34→    // Strip 0x prefix if present — DB stores bare hex
 35→    const normalizedPubKey = dto.recipientPublicKey.startsWith('0x')
 36→      ? dto.recipientPublicKey.slice(2)
 37→      : dto.recipientPublicKey;
 38→    const recipient = await this.userRepo.findOne({
 39→      where: { publicKey: normalizedPubKey },
 40→    });
 41→
 42→    if (!recipient) {
 43→      throw new NotFoundException('Recipient not found');
 44→    }
 45→
 46→    if (recipient.id === sharerId) {
 47→      throw new ConflictException('Cannot share with yourself');
 48→    }
 49→
 50→    // Check for existing active share (same sharer, recipient, ipnsName)
 51→    const existing = await this.shareRepo.findOne({
 52→      where: {
 53→        sharerId,
 54→        recipientId: recipient.id,
 55→        ipnsName: dto.ipnsName,
 56→        revokedAt: IsNull(),
 57→      },
 58→    });
 59→
 60→    if (existing) {
 61→      throw new ConflictException('Share already exists for this item and recipient');
 62→    }
 63→
 64→    // Clean up any revoked-but-not-yet-rotated records for this triple
 65→    // so the new share can be created without unique constraint conflicts
 66→    const revoked = await this.shareRepo.find({
 67→      where: {
 68→        sharerId,
 69→        recipientId: recipient.id,
 70→        ipnsName: dto.ipnsName,
 71→        revokedAt: Not(IsNull()),
 72→      },
 73→    });
 74→    if (revoked.length > 0) {
 75→      await this.shareRepo.remove(revoked);
 76→    }
 77→
 78→    const share = this.shareRepo.create({
 79→      sharerId,
 80→      recipientId: recipient.id,
 81→      itemType: dto.itemType,
 82→      ipnsName: dto.ipnsName,
 83→      itemName: dto.itemName,
 84→      encryptedKey: Buffer.from(dto.encryptedKey, 'hex'),
 85→      permission: dto.permission || 'read',
 86→      encryptedIpnsKey: dto.encryptedIpnsKey ? Buffer.from(dto.encryptedIpnsKey, 'hex') : null,
 87→      hiddenByRecipient: false,
 88→      revokedAt: null,
 89→    });
 90→
 91→    let savedShare: typeof share;
 92→    try {
 93→      savedShare = await this.shareRepo.save(share);
 94→    } catch (err: unknown) {
 95→      // Handle race condition: concurrent createShare for the same triple
 96→      if (err instanceof Error && err.message?.includes('duplicate key')) {
 97→        throw new ConflictException('Share already exists for this item and recipient');
 98→      }
 99→      throw err;
100→    }
101→
102→    // Create child keys if provided
103→    if (dto.childKeys && dto.childKeys.length > 0) {
104→      const shareKeys = dto.childKeys.map((ck) =>
105→        this.shareKeyRepo.create({
106→          shareId: savedShare.id,
107→          keyType: ck.keyType,
108→          itemId: ck.itemId,
109→          encryptedKey: Buffer.from(ck.encryptedKey, 'hex'),
110→        })
111→      );
112→      await this.shareKeyRepo.save(shareKeys);
113→    }
114→
115→    return savedShare;
116→  }
117→
118→  /**
119→   * Get active, non-hidden shares received by the user (paginated).
120→   * Includes sharer relation for publicKey display.
121→   */
122→  async getReceivedShares(
123→    recipientId: string,
124→    limit: number,
125→    offset: number
126→  ): Promise<{ shares: Share[]; total: number }> {
127→    const [shares, total] = await this.shareRepo.findAndCount({
128→      where: {
129→        recipientId,
130→        revokedAt: IsNull(),
131→        hiddenByRecipient: false,
132→      },
133→      relations: ['sharer'],
134→      order: { createdAt: 'DESC' },
135→      take: limit,
136→      skip: offset,
137→    });
138→    return { shares, total };
139→  }
140→
141→  /**
142→   * Get active shares sent by the user (paginated).
143→   * Includes recipient relation for publicKey display.
144→   */
145→  async getSentShares(
146→    sharerId: string,
147→    limit: number,
148→    offset: number
149→  ): Promise<{ shares: Share[]; total: number }> {
150→    const [shares, total] = await this.shareRepo.findAndCount({
151→      where: {
152→        sharerId,
153→        revokedAt: IsNull(),
154→      },
155→      relations: ['recipient'],
156→      order: { createdAt: 'DESC' },
157→      take: limit,
158→      skip: offset,
159→    });
160→    return { shares, total };
161→  }
162→
163→  /**
164→   * Get all re-wrapped child keys for a share.
165→   * Validates the requesting user is either sharer or recipient.
166→   */
167→  async getShareKeys(shareId: string, userId: string): Promise<ShareKey[]> {
168→    const share = await this.shareRepo.findOne({ where: { id: shareId } });
169→
170→    if (!share) {
171→      throw new NotFoundException('Share not found');
172→    }
173→
174→    if (share.sharerId !== userId && share.recipientId !== userId) {
175→      throw new ForbiddenException('Not authorized to access this share');
176→    }
177→
178→    return this.shareKeyRepo.find({
179→      where: { shareId },
180→      order: { createdAt: 'ASC' },
181→    });
182→  }
183→
184→  /**
185→   * Add or update re-wrapped keys for an existing share.
186→   * Allowed for the sharer (owner) or for write-share recipients.
187→   */
188→  async addShareKeys(shareId: string, callerId: string, dto: AddShareKeysDto): Promise<void> {
189→    const share = await this.shareRepo.findOne({ where: { id: shareId } });
190→
191→    if (!share) {
192→      throw new NotFoundException('Share not found');
193→    }
194→
195→    const isSharer = share.sharerId === callerId;
196→    const isWriteRecipient =
197→      share.recipientId === callerId && share.permission === 'write' && !share.revokedAt;
198→
199→    if (!isSharer && !isWriteRecipient) {
200→      throw new ForbiddenException('Only the sharer or write-share recipient can add keys');
201→    }
202→
203→    // Upsert: insert or update encrypted_key for each itemId
204→    for (const entry of dto.keys) {
205→      const existing = await this.shareKeyRepo.findOne({
206→        where: {
207→          shareId,
208→          keyType: entry.keyType,
209→          itemId: entry.itemId,
210→        },
211→      });
212→
213→      if (existing) {
214→        existing.encryptedKey = Buffer.from(entry.encryptedKey, 'hex');
215→        await this.shareKeyRepo.save(existing);
216→      } else {
217→        const shareKey = this.shareKeyRepo.create({
218→          shareId,
219→          keyType: entry.keyType,
220→          itemId: entry.itemId,
221→          encryptedKey: Buffer.from(entry.encryptedKey, 'hex'),
222→        });
223→        await this.shareKeyRepo.save(shareKey);
224→      }
225→    }
226→  }
227→
228→  /**
229→   * Soft-delete a share by setting revokedAt.
230→   * Only the sharer can revoke. ShareKey records are kept for lazy rotation.
231→   */
232→  async revokeShare(shareId: string, sharerId: string): Promise<void> {
233→    const share = await this.shareRepo.findOne({ where: { id: shareId } });
234→
235→    if (!share) {
236→      throw new NotFoundException('Share not found');
237→    }
238→
239→    if (share.sharerId !== sharerId) {
240→      throw new ForbiddenException('Only the sharer can revoke a share');
241→    }
242→
243→    share.revokedAt = new Date();
244→    await this.shareRepo.save(share);
245→  }
246→
247→  /**
248→   * Hide a share from the recipient's view.
249→   * Only the recipient can hide a share.
250→   */
251→  async hideShare(shareId: string, recipientId: string): Promise<void> {
252→    const share = await this.shareRepo.findOne({ where: { id: shareId } });
253→
254→    if (!share) {
255→      throw new NotFoundException('Share not found');
256→    }
257→
258→    if (share.recipientId !== recipientId) {
259→      throw new ForbiddenException('Only the recipient can hide a share');
260→    }
261→
262→    share.hiddenByRecipient = true;
263→    await this.shareRepo.save(share);
264→  }
265→
266→  /**
267→   * Check if a user with the given secp256k1 public key exists.
268→   * Used to verify recipient is registered before sharing.
269→   * Does not expose internal user IDs.
270→   */
271→  async lookupUserByPublicKey(publicKey: string): Promise<boolean> {
272→    // Strip 0x prefix if present — DB stores bare hex
273→    const normalizedKey = publicKey.startsWith('0x') ? publicKey.slice(2) : publicKey;
274→    const user = await this.userRepo.findOne({
275→      where: { publicKey: normalizedKey },
276→      select: ['id'],
277→    });
278→
279→    return !!user;
280→  }
281→
282→  /**
283→   * Get shares pending key rotation (revoked but not yet hard-deleted).
284→   */
285→  async getPendingRotations(sharerId: string): Promise<Share[]> {
286→    return this.shareRepo.find({
287→      where: {
288→        sharerId,
289→        revokedAt: Not(IsNull()),
290→      },
291→      relations: ['recipient'],
292→      order: { revokedAt: 'ASC' },
293→    });
294→  }
295→
296→  /**
297→   * Hard-delete a share and all associated keys after rotation is complete.
298→   * Only the sharer can complete the rotation.
299→   */
300→  async completeRotation(shareId: string, sharerId: string): Promise<void> {
301→    const share = await this.shareRepo.findOne({ where: { id: shareId } });
302→
303→    if (!share) {
304→      throw new NotFoundException('Share not found');
305→    }
306→
307→    if (share.sharerId !== sharerId) {
308→      throw new ForbiddenException('Only the sharer can complete rotation');
309→    }
310→
311→    if (!share.revokedAt) {
312→      throw new ConflictException('Cannot complete rotation for a non-revoked share');
313→    }
314→
315→    // CASCADE will remove all associated ShareKey records
316→    await this.shareRepo.remove(share);
317→  }
318→
319→  /**
320→   * Update the encrypted key on an existing share.
321→   * Used after lazy key rotation to re-wrap the new folder key for remaining recipients.
322→   */
323→  async updateShareEncryptedKey(
324→    shareId: string,
325→    sharerId: string,
326→    encryptedKey: string
327→  ): Promise<void> {
328→    const share = await this.shareRepo.findOne({ where: { id: shareId } });
329→
330→    if (!share) {
331→      throw new NotFoundException('Share not found');
332→    }
333→
334→    if (share.sharerId !== sharerId) {
335→      throw new ForbiddenException('Only the sharer can update share keys');
336→    }
337→
338→    share.encryptedKey = Buffer.from(encryptedKey, 'hex');
339→    await this.shareRepo.save(share);
340→  }
341→
342→  /**
343→   * Update the permission level of a share.
344→   * Only the sharer (owner) can upgrade or downgrade permission.
345→   * Upgrading to 'write' requires an ECIES-wrapped IPNS private key.
346→   * Downgrading to 'read' clears the IPNS key.
347→   */
348→  async updatePermission(
349→    shareId: string,
350→    sharerId: string,
351→    permission: 'read' | 'write',
352→    encryptedIpnsKey?: string
353→  ): Promise<void> {
354→    const share = await this.shareRepo.findOne({ where: { id: shareId } });
355→
356→    if (!share) {
357→      throw new NotFoundException('Share not found');
358→    }
359→
360→    if (share.sharerId !== sharerId) {
361→      throw new ForbiddenException('Only the sharer can change permission');
362→    }
363→
364→    if (permission === 'write') {
365→      if (!encryptedIpnsKey) {
366→        throw new BadRequestException('encryptedIpnsKey required for write permission');
367→      }
368→      share.permission = 'write';
369→      share.encryptedIpnsKey = Buffer.from(encryptedIpnsKey, 'hex');
370→    } else {
371→      share.permission = 'read';
372→      share.encryptedIpnsKey = null;
373→    }
374→
375→    await this.shareRepo.save(share);
376→  }
377→
378→  /**
379→   * Find an active write share for a given recipient and IPNS name.
380→   * Used by IPNS publish authorization to allow write-share recipients to publish.
381→   */
382→  async findActiveWriteShare(recipientId: string, ipnsName: string): Promise<Share | null> {
383→    return this.shareRepo.findOne({
384→      where: {
385→        recipientId,
386→        ipnsName,
387→        permission: 'write',
388→        revokedAt: IsNull(),
389→      },
390→    });
391→  }
392→}
