 28→@Injectable()
 29→export class IpnsService {
 30→  private readonly logger = new Logger(IpnsService.name);
 31→
 32→  constructor(
 33→    @InjectRepository(FolderIpns)
 34→    private readonly folderIpnsRepository: Repository<FolderIpns>,
 35→    private readonly delegatedRouting: DelegatedRoutingClient,
 36→    @Inject(forwardRef(() => RepublishService))
 37→    private readonly republishService: RepublishService,
 38→    private readonly metricsService: MetricsService,
 39→    private readonly sharesService: SharesService
 40→  ) {}
 41→
 42→  /**
 43→   * Publish a pre-signed IPNS record to the IPFS network via delegated routing
 44→   * and track the folder in the database for TEE republishing
 45→   */
 46→  async publishRecord(
 47→    userId: string,
 48→    dto: PublishIpnsDto | PublishIpnsEntryDto,
 49→    recordType: 'folder' | 'file' = 'folder'
 50→  ): Promise<PublishIpnsResponseDto> {
 51→    const endTimer = this.metricsService.ipfsIpnsDuration.startTimer({
 52→      operation: 'publish',
 53→      source: '',
 54→    });
 55→    let result = 'success';
 56→
 57→    try {
 58→      // Validate base64 record
 59→      let recordBytes: Uint8Array;
 60→      try {
 61→        recordBytes = Uint8Array.from(atob(dto.record), (c) => c.charCodeAt(0));
 62→      } catch {
 63→        throw new BadRequestException('Invalid base64-encoded record');
 64→      }
 65→
 66→      // Save to DB first so resolve always has a fallback, even if delegated
 67→      // routing fails (e.g. rate-limited, network error, DHT propagation delay).
 68→      const folder = await this.upsertFolderIpns(
 69→        userId,
 70→        dto.ipnsName,
 71→        dto.metadataCid,
 72→        dto.encryptedIpnsPrivateKey,
 73→        dto.keyEpoch,
 74→        recordType,
 75→        dto.expectedSequenceNumber
 76→      );
 77→
 78→      // Publish to delegated routing API (fire-and-forget — DB is the reliable source).
 79→      // DHT propagation via someguy takes ~10-30s per record. Since the DB record
 80→      // is already saved and resolveRecord() always checks/prefers DB data, there is
 81→      // no need to block the API response on DHT propagation. Metrics are still
 82→      // collected via the detached promise chain (catch + then).
 83→      const publishStart = process.hrtime.bigint();
 84→      this.delegatedRouting
 85→        .publish(dto.ipnsName, recordBytes)
 86→        .catch((error) => {
 87→          this.logger.warn(
 88→            `Delegated routing publish failed for ${dto.ipnsName}, DB record saved: ${error instanceof Error ? error.message : String(error)}`
 89→          );
 90→          return 'error' as const;
 91→        })
 92→        .then((outcome) => {
 93→          const publishElapsed = Number(process.hrtime.bigint() - publishStart) / 1e9;
 94→          this.metricsService.ipnsPublishDuration.observe(
 95→            { outcome: outcome === 'error' ? 'error' : 'success' },
 96→            publishElapsed
 97→          );
 98→        })
 99→        .catch((error) => {
100→          this.logger.error(
101→            `Failed to record IPNS publish metrics for ${dto.ipnsName}: ${error instanceof Error ? error.message : String(error)}`
102→          );
103→        });
104→
105→      return {
106→        success: true,
107→        ipnsName: dto.ipnsName,
108→        sequenceNumber: folder.sequenceNumber,
109→      };
110→    } catch (error) {
111→      result = 'error';
112→      throw error;
113→    } finally {
114→      endTimer({ result });
115→    }
116→  }
117→
118→  /**
119→   * Batch publish multiple IPNS records with concurrency-limited processing.
120→   * Supports partial success: individual record failures do not fail the batch.
121→   * Processes up to 10 records concurrently.
122→   */
123→  async publishBatch(
124→    userId: string,
125→    dto: BatchPublishIpnsDto
126→  ): Promise<BatchPublishIpnsResponseDto> {
127→    const results: PublishIpnsResponseDto[] = [];
128→    let totalSucceeded = 0;
129→    let totalFailed = 0;
130→
131→    const CONCURRENCY = 10;
132→
133→    // Process records in batches of CONCURRENCY, delegating to publishRecord
134→    for (let i = 0; i < dto.records.length; i += CONCURRENCY) {
135→      const batch = dto.records.slice(i, i + CONCURRENCY);
136→
137→      const settled = await Promise.allSettled(
138→        batch.map((entry) => this.publishRecord(userId, entry, entry.recordType ?? 'folder'))
139→      );
140→
141→      for (let j = 0; j < settled.length; j++) {
142→        const result = settled[j];
143→        if (result.status === 'fulfilled') {
144→          results.push(result.value);
145→          totalSucceeded++;
146→        } else {
147→          const reason = result.reason;
148→          // If any record (especially a folder record) has a conflict, fail the entire batch
149→          if (reason instanceof ConflictException) {
150→            throw reason;
151→          }
152→          const ipnsName = batch[j]?.ipnsName ?? 'unknown';
153→          this.logger.warn(
154→            `Batch publish failed for ${ipnsName}: ${reason instanceof Error ? reason.message : String(reason)}`
155→          );
156→          results.push({
157→            success: false,
158→            ipnsName,
159→            sequenceNumber: '0',
160→          });
161→          totalFailed++;
162→        }
163→      }
164→    }
165→
166→    return { results, totalSucceeded, totalFailed };
167→  }
168→
169→  /**
170→   * Create or update a folder/file IPNS entry.
171→   * Handles both folder metadata and per-file metadata IPNS records.
172→   */
173→  private async upsertFolderIpns(
174→    userId: string,
175→    ipnsName: string,
176→    metadataCid: string,
177→    encryptedIpnsPrivateKey?: string,
178→    keyEpoch?: number,
179→    recordType: 'folder' | 'file' = 'folder',
180→    expectedSequenceNumber?: string
181→  ): Promise<FolderIpns> {
182→    let existing = await this.getFolderIpns(userId, ipnsName);
183→
184→    // If not the owner, check for active write share authorization.
185→    // When no owner record is found AND a write share exists, look up
186→    // the owner's FolderIpns by ipnsName. When no write share exists,
187→    // fall through to the create-new-entry path (owner's first publish).
188→    if (!existing) {
189→      const writeShare = await this.sharesService.findActiveWriteShare(userId, ipnsName);
190→      if (writeShare) {
191→        // Look up the actual FolderIpns record by ipnsName (owned by the sharer)
192→        existing = await this.folderIpnsRepository.findOne({ where: { ipnsName } });
193→        if (!existing) {
194→          throw new NotFoundException('IPNS name not found');
195→        }
196→      }
197→    }
198→
199→    // Conflict detection: when expectedSequenceNumber is provided, verify it matches
200→    if (existing && expectedSequenceNumber !== undefined) {
201→      const expected = BigInt(expectedSequenceNumber);
202→      const current = BigInt(existing.sequenceNumber);
203→      if (expected !== current) {
204→        throw new ConflictException({
205→          statusCode: 409,
206→          message: 'Sequence number mismatch: folder was modified by another device',
207→          currentSequenceNumber: existing.sequenceNumber,
208→          expectedSequenceNumber,
209→        });
210→      }
211→    }
212→
213→    if (existing) {
214→      // Update existing entry
215→      existing.latestCid = metadataCid;
216→      existing.sequenceNumber = (BigInt(existing.sequenceNumber) + 1n).toString();
217→      existing.recordType = recordType;
218→      existing.updatedAt = new Date();
219→
220→      // Only update encrypted key if provided (e.g., on key rotation)
221→      if (encryptedIpnsPrivateKey && keyEpoch !== undefined) {
222→        existing.encryptedIpnsPrivateKey = Buffer.from(encryptedIpnsPrivateKey, 'hex');
223→        existing.keyEpoch = keyEpoch;
224→      }
225→
226→      const saved = await this.folderIpnsRepository.save(existing);
227→
228→      // Auto-enroll for TEE republishing when encrypted key is provided.
229→      // Use existing.userId (the FolderIpns owner) for enrollment, not the
230→      // authenticated user — a write-share recipient publishes to the owner's record.
231→      if (encryptedIpnsPrivateKey && keyEpoch !== undefined) {
232→        this.republishService
233→          .enrollFolder(
234→            existing.userId,
235→            ipnsName,
236→            Buffer.from(encryptedIpnsPrivateKey, 'hex'),
237→            keyEpoch,
238→            metadataCid,
239→            saved.sequenceNumber
240→          )
241→          .catch((err) =>
242→            this.logger.warn(
243→              `Failed to enroll ${recordType} ${ipnsName} for republishing: ${err.message}`
244→            )
245→          );
246→      }
247→
248→      return saved;
249→    }
250→
251→    // Create new entry — sequence starts at '1' to match the IPNS record
252→    // the client signed (clients compute newSeq = 0n + 1n = 1n for first publish).
253→    const folder = this.folderIpnsRepository.create({
254→      userId,
255→      ipnsName,
256→      latestCid: metadataCid,
257→      sequenceNumber: '1',
258→      encryptedIpnsPrivateKey: encryptedIpnsPrivateKey
259→        ? Buffer.from(encryptedIpnsPrivateKey, 'hex')
260→        : null,
261→      keyEpoch: keyEpoch ?? null,
262→      isRoot: false, // Root folder is tracked in Vault entity
263→      recordType,
264→    });
265→
266→    const saved = await this.folderIpnsRepository.save(folder);
267→
268→    // Auto-enroll for TEE republishing when encrypted key is provided
269→    if (encryptedIpnsPrivateKey && keyEpoch !== undefined) {
270→      this.republishService
271→        .enrollFolder(
272→          userId,
273→          ipnsName,
274→          Buffer.from(encryptedIpnsPrivateKey, 'hex'),
275→          keyEpoch,
276→          metadataCid,
277→          saved.sequenceNumber
278→        )
279→        .catch((err) =>
280→          this.logger.warn(
281→            `Failed to enroll ${recordType} ${ipnsName} for republishing: ${err.message}`
282→          )
283→        );
284→    }
285→
286→    return saved;
287→  }
