 34→/**
 35→ * Truncate a public key for display: 0x{first4}...{last4}
 36→ */
 37→function truncatePubkey(pubkey: string): string {
 38→  if (pubkey.length <= 12) return pubkey;
 39→  const hex = pubkey.startsWith('0x') ? pubkey.slice(2) : pubkey;
 40→  return `0x${hex.slice(0, 4)}...${hex.slice(-4)}`;
 41→}
 42→
 43→/**
 44→ * Sort items: folders first, then files, both alphabetically.
 45→ */
 46→function sortItems(items: FolderChild[]): FolderChild[] {
 47→  return [...items].sort((a, b) => {
 48→    if (a.type === 'folder' && b.type !== 'folder') return -1;
 49→    if (a.type !== 'folder' && b.type === 'folder') return 1;
 50→    return a.name.localeCompare(b.name, undefined, { sensitivity: 'base' });
 51→  });
 52→}
