763→/**
764→ * Row component for the top-level shared items list.
765→ */
766→function SharedListRow({
767→  sharedItem,
768→  onOpen,
769→  onContextMenu,
770→}: {
771→  sharedItem: SharedListItem;
772→  onOpen: () => void;
773→  onContextMenu: (e: MouseEvent) => void;
774→}) {
775→  const { share } = sharedItem;
776→  const isFolder = share.itemType === 'folder';
777→  const icon = isFolder ? '\uD83D\uDCC1' : '\uD83D\uDCC4';
778→  const date = new Date(share.createdAt).toLocaleDateString();
779→  const isWrite = share.permission === 'write';
780→
781→  return (
782→    <div
783→      className="file-list-row shared-list-row"
784→      role="row"
785→      tabIndex={0}
786→      onDoubleClick={onOpen}
787→      onContextMenu={(e) => {
788→        e.preventDefault();
789→        onContextMenu(e);
790→      }}
791→      onKeyDown={(e) => {
792→        if (e.key === 'Enter' || e.key === ' ') {
793→          e.preventDefault();
794→          onOpen();
795→        }
796→      }}
797→    >
798→      <div className="file-list-cell file-list-cell-name" role="gridcell">
799→        <span className="file-icon">{icon}</span>
800→        <span className="file-name">
801→          {share.itemName}
802→          {isFolder ? '/' : ''}
803→        </span>
804→        {isWrite ? (
805→          <span className="shared-rw-badge">{'[RW]'}</span>
806→        ) : (
807→          <span className="shared-ro-badge">{'[RO]'}</span>
808→        )}
809→      </div>
810→      <div className="file-list-cell shared-by-cell" role="gridcell">
811→        {truncatePubkey(share.sharerPublicKey)}
812→      </div>
813→      <div className="file-list-cell file-list-cell-date" role="gridcell">
814→        {date}
815→      </div>
816→    </div>
817→  );
818→}
