838→  permission: 'read' | 'write' | null;
839→  isRenaming: boolean;
840→  renameValue: string;
841→  renameInputRef: React.RefObject<HTMLInputElement>;
842→  onRenameChange: (value: string) => void;
843→  onRenameKeyDown: (e: React.KeyboardEvent) => void;
844→  onRenameSubmit: () => void;
845→  onContextMenu: (e: MouseEvent) => void;
