 20→import { updateSharePermission } from '../../services/share.service';
 21→import { InviteLinkTab } from './InviteLinkTab';
 22→import '../../styles/share-dialog.css';
 23→
 24→type ShareDialogProps = {
 25→  isOpen: boolean;
 26→  onClose: () => void;
 27→  item: FolderChild;
 28→  folderKey: Uint8Array;
 29→  ipnsName: string;
 30→  parentFolderId: string;
 31→};
 32→
 33→/** Sent share record from the API */
 34→type SentShare = {
 35→  shareId: string;
 36→  recipientPublicKey: string;
 37→  itemType: string;
 38→  ipnsName: string;
 39→  itemName: string;
 40→  permission: 'read' | 'write';
 41→  createdAt: string;
 42→};
 43→
 44→/**
 45→ * Validate public key format: must be 0x04 prefix + 128 hex chars (64 bytes body = 65 bytes total uncompressed).
 46→ */
 47→function isValidPublicKey(key: string): boolean {
 48→  if (!key.startsWith('0x04')) return false;
 49→  // 0x + 130 hex chars = 65 bytes uncompressed secp256k1
 50→  const hexPart = key.slice(2);
 51→  if (hexPart.length !== 130) return false;
 52→  return /^[0-9a-fA-F]+$/.test(hexPart);
 53→}
 54→
 55→/**
 56→ * Truncate a public key for display: 0x{first4}...{last4}
 57→ */
 58→function truncateKey(key: string): string {
 59→  if (key.length < 12) return key;
 60→  const hex = key.startsWith('0x') ? key.slice(2) : key;
 61→  return `0x${hex.slice(0, 4)}...${hex.slice(-4)}`;
 62→}
 63→
 64→/**
 65→ * Share dialog modal for creating and managing shares.
 66→ *
 67→ * Allows users to:
 68→ * - Paste a recipient's public key and create a share
 69→ * - View existing recipients with truncated pubkeys
 70→ * - Revoke individual recipients with inline confirm
 71→ *
 72→ * For folders, traverses all descendants and re-wraps keys.
 73→ * For files, wraps the single file key for the recipient.
 74→ */
 75→export function ShareDialog({
 76→  isOpen,
 77→  onClose,
 78→  item,
 79→  folderKey,
 80→  ipnsName,
 81→  parentFolderId,
 82→}: ShareDialogProps) {
 83→  const [activeTab, setActiveTab] = useState<'direct' | 'invite'>('direct');
 84→  const [pubKeyInput, setPubKeyInput] = useState('');
 85→  const [error, setError] = useState<string | null>(null);
 86→  const [success, setSuccess] = useState<string | null>(null);
 87→  const [isSharing, setIsSharing] = useState(false);
 88→  const [progress, setProgress] = useState<{ current: number; total: number } | null>(null);
 89→  const [recipients, setRecipients] = useState<SentShare[]>([]);
 90→  const [recipientsLoading, setRecipientsLoading] = useState(false);
 91→  const [recipientsFetched, setRecipientsFetched] = useState(false);
 92→  const [permission, setPermission] = useState<'read' | 'write'>('read');
 93→  const [confirmRevokeId, setConfirmRevokeId] = useState<string | null>(null);
 94→  const [revokingId, setRevokingId] = useState<string | null>(null);
 95→  const [confirmDowngradeId, setConfirmDowngradeId] = useState<string | null>(null);
 96→  const [upgradingId, setUpgradingId] = useState<string | null>(null);
 97→  const [downgradingId, setDowngradingId] = useState<string | null>(null);
 98→
 99→  const inputRef = useRef<HTMLInputElement>(null);
100→  const directTabRef = useRef<HTMLButtonElement>(null);
101→  const inviteTabRef = useRef<HTMLButtonElement>(null);
102→
103→  // Fetch existing recipients when dialog opens
104→  useEffect(() => {
105→    if (!isOpen) {
106→      // Reset state on close
107→      setActiveTab('direct');
108→      setPubKeyInput('');
109→      setError(null);
110→      setSuccess(null);
111→      setIsSharing(false);
112→      setProgress(null);
113→      setPermission('read');
114→      setConfirmRevokeId(null);
115→      setRevokingId(null);
116→      setConfirmDowngradeId(null);
117→      setUpgradingId(null);
118→      setDowngradingId(null);
119→      setRecipients([]);
120→      setRecipientsLoading(false);
121→      setRecipientsFetched(false);
122→      return;
123→    }
124→
125→    let cancelled = false;
126→    setRecipientsLoading(true);
127→
128→    (async () => {
129→      const pageSize = 100;
130→      let offset = 0;
131→      const allShares: SentShare[] = [];
132→
133→      // Paginate through all sent shares (API max 100 per page)
134→
135→      while (true) {
136→        const response = await sharesControllerGetSentShares({ limit: pageSize, offset });
137→        if (cancelled) return;
138→        const pageShares = response.shares
139→          .filter((s) => s.ipnsName === ipnsName)
140→          .map((s) => ({
141→            shareId: s.shareId,
142→            recipientPublicKey: s.recipientPublicKey,
143→            itemType: s.itemType as 'folder' | 'file',
144→            ipnsName: s.ipnsName,
145→            itemName: s.itemName,
146→            permission: ((s.permission as 'read' | 'write') ?? 'read') as 'read' | 'write',
147→            createdAt: String(s.createdAt),
148→          }));
149→        allShares.push(...pageShares);
150→        offset += response.shares.length;
151→        if (offset >= response.total || response.shares.length === 0) break;
152→      }
153→
154→      if (cancelled) return;
155→      setRecipients(allShares);
156→    })()
157→      .catch((err) => {
158→        if (cancelled) return;
159→        console.error('Failed to fetch sent shares:', err);
160→      })
161→      .finally(() => {
162→        if (!cancelled) {
163→          setRecipientsLoading(false);
164→          setRecipientsFetched(true);
165→        }
166→      });
167→
168→    return () => {
169→      cancelled = true;
170→    };
171→  }, [isOpen, ipnsName]);
172→
173→  const handleShare = useCallback(async () => {
174→    setError(null);
175→    setSuccess(null);
176→
177→    const key = pubKeyInput.trim();
178→
179→    // Validate format
180→    if (!isValidPublicKey(key)) {
181→      setError('invalid key format -- expected 0x04 + 128 hex chars');
182→      return;
183→    }
184→
185→    // Prevent sharing root folder
186→    if (parentFolderId === 'root' && item.type === 'folder') {
187→      // Check if item is the root folder itself (the one navigated to at root)
188→      const rootFolder = useFolderStore.getState().folders['root'];
189→      if (rootFolder && item.id === 'root') {
190→        setError('cannot share root folder');
191→        return;
192→      }
193→    }
194→
195→    // Check not sharing with yourself
196→    const vaultKeypair = useAuthStore.getState().vaultKeypair;
197→    if (!vaultKeypair) {
198→      setError('vault keypair not available');
199→      return;
200→    }
201→
202→    const myPubKeyHex = '0x' + bytesToHex(vaultKeypair.publicKey);
203→    if (key.toLowerCase() === myPubKeyHex.toLowerCase()) {
204→      setError('cannot share with yourself');
205→      return;
206→    }
207→
208→    setIsSharing(true);
209→
210→    try {
211→      // Verify recipient is a registered user
212→      const lookup = await sharesControllerLookupUser({ publicKey: key });
213→      if (!lookup.exists) {
214→        setError('user not found');
215→        setIsSharing(false);
216→        return;
217→      }
218→    } catch {
219→      setError('lookup failed, please try again');
220→      setIsSharing(false);
221→      return;
222→    }
223→
224→    try {
225→      const recipientPubKeyBytes = hexToBytes(key.slice(2));
226→      const ownerPrivateKey = vaultKeypair.privateKey;
227→
228→      let encryptedKey: string;
229→      let childKeys: ChildKeyDto[] | undefined;
230→      let encryptedIpnsKeyHex: string | undefined;
231→
232→      if (item.type === 'folder') {
233→        const folderEntry = item as FolderEntry;
234→
235→        // Unwrap the folder's own key from its ECIES-encrypted form
236→        const itemFolderKey = await unwrapKey(
237→          hexToBytes(folderEntry.folderKeyEncrypted),
238→          ownerPrivateKey
239→        );
240→
241→        try {
242→          // Wrap the folder key for the recipient
243→          const wrappedForRecipient = await wrapKey(itemFolderKey, recipientPubKeyBytes);
244→          encryptedKey = bytesToHex(wrappedForRecipient);
245→
246→          // For write shares, also wrap the IPNS private key for the recipient
247→          if (permission === 'write') {
248→            const ipnsPrivKey = await unwrapKey(
249→              hexToBytes(folderEntry.ipnsPrivateKeyEncrypted),
250→              ownerPrivateKey
251→            );
252→            try {
253→              const wrappedIpnsKey = await wrapKey(ipnsPrivKey, recipientPubKeyBytes);
254→              encryptedIpnsKeyHex = bytesToHex(wrappedIpnsKey);
255→            } finally {
256→              ipnsPrivKey.fill(0);
257→            }
258→          }
259→
260→          // Traverse children and re-wrap descendant keys
261→          const resolved = await resolveIpnsRecord(folderEntry.ipnsName);
262→          if (resolved) {
263→            const encryptedBytes = await fetchFromIpfs(resolved.cid);
264→            const encryptedJson = new TextDecoder().decode(encryptedBytes);
265→            const encrypted = JSON.parse(encryptedJson);
266→            const metadata = await decryptFolderMetadata(encrypted, itemFolderKey);
267→
268→            setProgress({ current: 0, total: 0 });
269→
270→            childKeys = await collectChildKeys(
271→              metadata.children,
272→              itemFolderKey,
273→              ownerPrivateKey,
274→              recipientPubKeyBytes,
275→              (wrapped) => setProgress({ current: wrapped, total: 0 })
276→            );
277→          }
278→        } finally {
279→          itemFolderKey.fill(0);
280→        }
281→      } else {
282→        // File sharing: wrap parent folder key for recipient (needed to decrypt file metadata),
283→        // and re-wrap the file key as a child key entry
284→        const filePointer = item as FilePointer;
285→
286→        // encryptedKey = parent folder key wrapped for recipient
287→        const wrappedFolderKey = await wrapKey(folderKey, recipientPubKeyBytes);
288→        encryptedKey = bytesToHex(wrappedFolderKey);
289→
290→        // Re-wrap the file key for the recipient and store as child key
291→        const { metadata: fileMeta } = await resolveFileMetadata(
292→          filePointer.fileMetaIpnsName,
293→          folderKey
294→        );
295→        const reWrappedFileKey = await reWrapEncryptedKey(
296→          fileMeta.fileKeyEncrypted,
297→          ownerPrivateKey,
298→          recipientPubKeyBytes
299→        );
300→        childKeys = [
301→          { keyType: 'file' as const, itemId: filePointer.id, encryptedKey: reWrappedFileKey },
302→        ];
303→      }
304→
305→      // Create the share via API
306→      const itemType: CreateShareDtoItemType = item.type === 'folder' ? 'folder' : 'file';
307→      const result = await sharesControllerCreateShare({
308→        recipientPublicKey: key,
309→        itemType,
310→        ipnsName,
311→        itemName: item.name,
312→        encryptedKey,
313→        permission,
314→        encryptedIpnsKey: encryptedIpnsKeyHex,
315→        childKeys: childKeys && childKeys.length > 0 ? childKeys : undefined,
316→      });
317→
318→      // Update local recipients list and global store (for re-wrapping cache)
319→      const newShare = {
320→        shareId: result.shareId,
321→        recipientPublicKey: key,
322→        itemType: item.type as 'folder' | 'file',
323→        ipnsName,
324→        itemName: item.name,
325→        permission,
326→        createdAt: new Date().toISOString(),
327→      };
328→      setRecipients((prev) => [...prev, newShare]);
329→      useShareStore.getState().addSentShare(newShare);
330→
331→      setSuccess(
332→        permission === 'write'
333→          ? `shared (read-write) with ${truncateKey(key)}`
334→          : `shared with ${truncateKey(key)}`
335→      );
336→      setPubKeyInput('');
337→      setProgress(null);
338→    } catch (err) {
339→      console.error('Share creation failed:', err);
340→      const message = err instanceof Error ? err.message : 'share creation failed';
341→      setError(message);
342→    } finally {
343→      setIsSharing(false);
344→      setProgress(null);
345→    }
346→  }, [pubKeyInput, item, folderKey, ipnsName, parentFolderId, permission]);
347→
348→  const handleRevoke = useCallback(async (shareId: string) => {
349→    setRevokingId(shareId);
350→    setConfirmRevokeId(null);
351→    try {
352→      await sharesControllerRevokeShare(shareId);
353→      setRecipients((prev) => prev.filter((r) => r.shareId !== shareId));
354→      useShareStore.getState().removeSentShare(shareId);
355→    } catch (err) {
356→      console.error('Revoke failed:', err);
357→      setError('revoke failed');
358→    } finally {
359→      setRevokingId(null);
360→    }
361→  }, []);
362→
363→  const handleUpgrade = useCallback(
364→    async (share: SentShare) => {
365→      setError(null);
366→      setSuccess(null);
367→      setUpgradingId(share.shareId);
368→
369→      try {
370→        // Get vault keypair for unwrapping IPNS key
371→        const vaultKeypair = useAuthStore.getState().vaultKeypair;
372→        if (!vaultKeypair) {
373→          setError('vault keypair not available');
374→          return;
375→        }
376→
377→        // The item must be a folder to upgrade (file shares don't have IPNS keys)
378→        if (item.type !== 'folder') {
379→          setError('permission upgrade only applies to folder shares');
380→          return;
381→        }
382→
383→        const folderEntry = item as FolderEntry;
384→        const ownerPrivateKey = vaultKeypair.privateKey;
385→        const recipientPubKeyBytes = hexToBytes(
386→          share.recipientPublicKey.startsWith('0x')
387→            ? share.recipientPublicKey.slice(2)
388→            : share.recipientPublicKey
389→        );
390→
391→        // Unwrap IPNS private key and re-wrap for recipient
392→        const ipnsPrivKey = await unwrapKey(
393→          hexToBytes(folderEntry.ipnsPrivateKeyEncrypted),
394→          ownerPrivateKey
395→        );
396→        let encryptedIpnsKeyHex: string;
397→        try {
398→          const wrappedIpnsKey = await wrapKey(ipnsPrivKey, recipientPubKeyBytes);
399→          encryptedIpnsKeyHex = bytesToHex(wrappedIpnsKey);
400→        } finally {
401→          ipnsPrivKey.fill(0);
402→        }
403→
404→        await updateSharePermission(share.shareId, 'write', encryptedIpnsKeyHex);
405→
406→        // Update local state
407→        setRecipients((prev) =>
408→          prev.map((r) => (r.shareId === share.shareId ? { ...r, permission: 'write' } : r))
409→        );
410→        useShareStore.getState().updateSentSharePermission(share.shareId, 'write');
411→        setSuccess('> upgraded to read-write');
412→      } catch (err) {
413→        console.error('Permission upgrade failed:', err);
414→        setError('> permission change failed, please try again');
415→      } finally {
416→        setUpgradingId(null);
417→      }
418→    },
419→    [item]
420→  );
421→
422→  const handleDowngradeConfirm = useCallback(async (share: SentShare) => {
423→    setError(null);
424→    setSuccess(null);
425→    setDowngradingId(share.shareId);
426→    setConfirmDowngradeId(null);
427→
428→    try {
429→      await updateSharePermission(share.shareId, 'read');
430→
431→      // Update local state
432→      setRecipients((prev) =>
433→        prev.map((r) => (r.shareId === share.shareId ? { ...r, permission: 'read' } : r))
434→      );
435→      useShareStore.getState().updateSentSharePermission(share.shareId, 'read');
436→      setSuccess('> downgraded to read-only');
437→    } catch (err) {
438→      console.error('Permission downgrade failed:', err);
439→      setError('> permission change failed, please try again');
440→    } finally {
441→      setDowngradingId(null);
442→    }
443→  }, []);
444→
445→  const handleKeyDown = useCallback(
446→    (e: React.KeyboardEvent) => {
447→      if (e.key === 'Enter' && !isSharing) {
448→        handleShare();
449→      }
450→    },
451→    [handleShare, isSharing]
452→  );
453→
454→  const itemDisplayName = item.type === 'folder' ? `${item.name}/` : item.name;
455→  const title = `SHARE: ${itemDisplayName}`;
456→
457→  return (
458→    <Modal open={isOpen} onClose={onClose} title={title} className="share-dialog-backdrop">
459→      <div className="share-dialog">
460→        {/* Tab bar */}
461→        <div className="share-tab-bar" role="tablist" aria-label="Share method">
462→          <button
463→            ref={directTabRef}
464→            type="button"
465→            role="tab"
466→            id="share-tab-direct"
467→            aria-selected={activeTab === 'direct'}
468→            aria-controls="share-panel-direct"
469→            tabIndex={activeTab === 'direct' ? 0 : -1}
470→            className={`share-tab${activeTab === 'direct' ? ' share-tab--active' : ''}`}
471→            onClick={() => setActiveTab('direct')}
472→            onKeyDown={(e) => {
473→              if (e.key === 'ArrowRight') {
474→                e.preventDefault();
475→                setActiveTab('invite');
476→                inviteTabRef.current?.focus();
477→              }
478→            }}
479→          >
480→            {'DIRECT SHARE'}
481→          </button>
482→          <button
483→            ref={inviteTabRef}
484→            type="button"
485→            role="tab"
486→            id="share-tab-invite"
487→            aria-selected={activeTab === 'invite'}
488→            aria-controls="share-panel-invite"
489→            tabIndex={activeTab === 'invite' ? 0 : -1}
490→            className={`share-tab${activeTab === 'invite' ? ' share-tab--active' : ''}`}
491→            onClick={() => setActiveTab('invite')}
492→            onKeyDown={(e) => {
493→              if (e.key === 'ArrowLeft') {
494→                e.preventDefault();
495→                setActiveTab('direct');
496→                directTabRef.current?.focus();
497→              }
498→            }}
499→          >
500→            {'INVITE LINK'}
501→          </button>
502→        </div>
503→
504→        {/* Direct Share tab panel */}
505→        {activeTab === 'direct' && (
506→          <div role="tabpanel" id="share-panel-direct" aria-labelledby="share-tab-direct">
507→            {/* Input section */}
508→            <div className="share-input-section">
509→              <label className="share-input-label" htmlFor="share-pubkey-input">
510→                {'// paste recipient public key'}
511→              </label>
512→              <div className="share-input-row">
513→                <input
514→                  ref={inputRef}
515→                  id="share-pubkey-input"
516→                  type="text"
517→                  className={`share-input${error ? ' share-input--error' : ''}`}
518→                  placeholder="0x04..."
519→                  value={pubKeyInput}
520→                  onChange={(e) => {
521→                    setPubKeyInput(e.target.value);
522→                    setError(null);
523→                    setSuccess(null);
524→                  }}
525→                  onKeyDown={handleKeyDown}
526→                  disabled={isSharing}
527→                  autoComplete="off"
528→                  spellCheck={false}
529→                />
530→                <button
531→                  type="button"
532→                  className="share-submit-btn"
533→                  onClick={handleShare}
534→                  disabled={isSharing || !pubKeyInput.trim()}
535→                >
536→                  {isSharing ? '...' : '--share'}
537→                </button>
538→              </div>
539→
540→              {/* Permission toggle */}
541→              {item.type === 'folder' && (
542→                <div className="share-permission-selector">
543→                  <label className="share-permission-label">{'// permission'}</label>
544→                  <div
545→                    className="share-permission-toggle"
546→                    role="radiogroup"
547→                    aria-label="Permission level"
548→                    onKeyDown={(e) => {
549→                      if (e.key === 'ArrowRight' || e.key === 'ArrowLeft') {
550→                        e.preventDefault();
551→                        setPermission((prev) => (prev === 'read' ? 'write' : 'read'));
552→                      }
553→                    }}
554→                  >
555→                    <button
556→                      type="button"
557→                      role="radio"
558→                      aria-checked={permission === 'read'}
559→                      tabIndex={permission === 'read' ? 0 : -1}
560→                      className={`share-perm-btn${permission === 'read' ? ' share-perm-btn--active' : ''}`}
561→                      onClick={() => setPermission('read')}
562→                    >
563→                      {'[ READ-ONLY ]'}
564→                    </button>
565→                    <button
566→                      type="button"
567→                      role="radio"
568→                      aria-checked={permission === 'write'}
569→                      tabIndex={permission === 'write' ? 0 : -1}
570→                      className={`share-perm-btn${permission === 'write' ? ' share-perm-btn--active' : ''}`}
571→                      onClick={() => setPermission('write')}
572→                    >
573→                      {'[ READ-WRITE ]'}
574→                    </button>
575→                  </div>
576→                </div>
577→              )}
578→
579→              {/* Error message */}
580→              {error && (
581→                <div className="share-error" role="alert">
582→                  {'> '}
583→                  {error}
584→                </div>
585→              )}
586→
587→              {/* Success message */}
588→              {success && (
589→                <div className="share-success" role="status">
590→                  {'> '}
591→                  {success}
592→                </div>
593→              )}
594→
595→              {/* Progress indicator for folder sharing */}
596→              {progress && (
597→                <div className="share-progress" role="status" aria-live="polite">
598→                  {'> '}re-wrapping keys... {progress.current}
599→                </div>
600→              )}
601→            </div>
602→
603→            {/* Recipients section */}
604→            <div className="share-recipients-section">
605→              <div className="share-recipients-header">{'// recipients'}</div>
606→
607→              {recipientsLoading || !recipientsFetched ? (
608→                <div className="share-recipients-loading">loading...</div>
609→              ) : recipients.length === 0 ? (
610→                <div className="share-recipients-empty">no recipients yet</div>
611→              ) : (
612→                <div className="share-recipients-list">
613→                  {recipients.map((recipient) => (
614→                    <div key={recipient.shareId} className="share-recipient">
615→                      <span className="share-recipient-key">
616→                        {truncateKey(recipient.recipientPublicKey)}
617→                      </span>
618→                      <span
619→                        className={
620→                          recipient.permission === 'write'
621→                            ? 'recipient-perm-write'
622→                            : 'recipient-perm-read'
623→                        }
624→                      >
625→                        {recipient.permission === 'write' ? '[write]' : '[read]'}
626→                      </span>
627→
628→                      <div className="share-recipient-actions">
629→                        {/* Upgrade/downgrade controls (folders only) */}
630→                        {item.type === 'folder' && (
631→                          <>
632→                            {recipient.permission === 'read' ? (
633→                              <button
634→                                type="button"
635→                                className="share-action-btn share-upgrade-btn"
636→                                onClick={() => handleUpgrade(recipient)}
637→                                disabled={upgradingId !== null || downgradingId !== null}
638→                                aria-label={`Upgrade ${truncateKey(recipient.recipientPublicKey)} to read-write`}
639→                              >
640→                                {upgradingId === recipient.shareId ? '...' : '--upgrade'}
641→                              </button>
642→                            ) : confirmDowngradeId === recipient.shareId ? (
643→                              <div className="share-revoke-confirm">
644→                                <span className="share-revoke-confirm-text">{'confirm?'}</span>
645→                                <button
646→                                  type="button"
647→                                  className="share-revoke-confirm-btn share-revoke-confirm-btn--yes"
648→                                  onClick={() => handleDowngradeConfirm(recipient)}
649→                                  disabled={downgradingId === recipient.shareId}
650→                                  aria-label="Confirm downgrade"
651→                                >
652→                                  {downgradingId === recipient.shareId ? '...' : '[y]'}
653→                                </button>
654→                                <button
655→                                  type="button"
656→                                  className="share-revoke-confirm-btn share-revoke-confirm-btn--no"
657→                                  onClick={() => setConfirmDowngradeId(null)}
658→                                  aria-label="Cancel downgrade"
659→                                >
