  1→import { useState, useEffect, useCallback, useRef } from 'react';
  2→import type { FilePointer } from '@cipherbox/core';
  3→import { Modal } from '../ui/Modal';
  4→import { useAuthStore } from '../../stores/auth.store';
  5→import { useFolder } from '../../hooks/useFolder';
  6→import { downloadFile, triggerBrowserDownload } from '../../services/download.service';
  7→import { resolveFileMetadata } from '../../services/file-metadata.service';
  8→import { fetchShareKeys } from '../../services/share.service';
  9→import { getSdkClient, hasSdkClient } from '../../lib/sdk-provider';
 10→import { encryptFile } from '../../services/file-crypto.service';
 11→import { addToIpfs } from '../../lib/api/ipfs';
 12→import '../../styles/text-editor-dialog.css';
 13→
 14→type TextEditorDialogProps = {
 15→  open: boolean;
 16→  onClose: () => void;
 17→  item: FilePointer | null;
 18→  parentFolderId: string;
 19→  /** Parent folder's decrypted AES-256 key (needed to decrypt file metadata) */
 20→  folderKey: Uint8Array | null;
 21→  /** When true, textarea is read-only and save is hidden */
 22→  readOnly?: boolean;
 23→  /** Share ID when viewing from a shared folder — uses re-wrapped file keys */
 24→  shareId?: string | null;
 25→  /** Save handler for shared files — updates file IPNS metadata via shared path */
 26→  onSaveSharedFile?: (item: FilePointer, newContent: Uint8Array) => Promise<void>;
 27→};
 28→
 29→/**
 30→ * Modal dialog for viewing/editing text files in-browser.
 31→ *
 32→ * In edit mode (default): full crypto round-trip with save.
 33→ * In read-only mode: decrypt and display only (used for shared files).
 34→ */
 35→export function TextEditorDialog({
 36→  open,
 37→  onClose,
 38→  item,
 39→  parentFolderId,
 40→  folderKey,
 41→  readOnly,
 42→  shareId,
 43→  onSaveSharedFile,
 44→}: TextEditorDialogProps) {
 45→  const [loading, setLoading] = useState(false);
 46→  const [saving, setSaving] = useState(false);
 47→  const [content, setContent] = useState('');
 48→  const [originalContent, setOriginalContent] = useState('');
 49→  const [error, setError] = useState<string | null>(null);
 50→  const textareaRef = useRef<HTMLTextAreaElement>(null);
 51→
 52→  const { updateFile } = useFolder();
 53→
 54→  const isDirty = content !== originalContent;
 55→  const lineCount = content.split('\n').length;
 56→
 57→  // Load file content when dialog opens
 58→  useEffect(() => {
 59→    if (!open || !item) {
 60→      setContent('');
 61→      setOriginalContent('');
 62→      setError(null);
 63→      setLoading(false);
 64→      setSaving(false);
 65→      return;
 66→    }
 67→
 68→    if (!folderKey) {
 69→      setLoading(false);
 70→      setError('Folder key not available');
 71→      return;
 72→    }
 73→
 74→    if (!item.fileMetaIpnsName) {
 75→      setLoading(false);
 76→      setError('File metadata IPNS name not available (legacy v1 file?)');
 77→      return;
 78→    }
 79→
 80→    let cancelled = false;
 81→    let focusRaf: number | undefined;
 82→    setLoading(true);
 83→    setError(null);
 84→
 85→    (async () => {
 86→      try {
 87→        const auth = useAuthStore.getState();
 88→        if (!auth.vaultKeypair) {
 89→          throw new Error('No keypair available - please log in again');
 90→        }
 91→
 92→        let plaintext: Uint8Array;
 93→
 94→        if (shareId) {
 95→          // Shared file path: use re-wrapped file key from share_keys,
 96→          // falling back to fileKeyEncrypted from metadata (for files uploaded by current user)
 97→          const [{ metadata: fileMeta }, keys] = await Promise.all([
 98→            resolveFileMetadata(item.fileMetaIpnsName, folderKey!),
 99→            fetchShareKeys(shareId),
100→          ]);
101→
102→          const fileKeyRecord = keys.find((k) => k.keyType === 'file' && k.itemId === item.id);
103→          const wrappedKey = fileKeyRecord?.encryptedKey ?? fileMeta.fileKeyEncrypted;
104→
105→          plaintext = await downloadFile(
106→            {
107→              cid: fileMeta.cid,
108→              iv: fileMeta.fileIv,
109→              wrappedKey,
110→              originalName: item.name,
111→              encryptionMode: fileMeta.encryptionMode,
112→            },
113→            auth.vaultKeypair.privateKey
114→          );
115→        } else if (hasSdkClient()) {
116→          // Owner path via SDK: resolves IPNS, decrypts metadata, downloads + decrypts content
117→          const client = getSdkClient();
118→          plaintext = await client.downloadFromIpns(item.fileMetaIpnsName, folderKey!);
119→        } else {
120→          throw new Error('SDK not initialized — please log in again');
121→        }
122→
123→        if (cancelled) return;
124→
125→        const text = new TextDecoder().decode(plaintext);
126→        setContent(text);
127→        setOriginalContent(text);
128→        setLoading(false);
129→
130→        // Focus textarea after content loads (only in edit mode)
131→        if (!readOnly) {
132→          focusRaf = requestAnimationFrame(() => {
133→            textareaRef.current?.focus();
134→          });
135→        }
136→      } catch (err) {
137→        if (cancelled) return;
138→        setError(err instanceof Error ? err.message : 'Failed to load file');
139→        setLoading(false);
140→      }
141→    })();
142→
143→    return () => {
144→      cancelled = true;
145→      if (focusRaf !== undefined) cancelAnimationFrame(focusRaf);
146→    };
147→  }, [open, item, folderKey, shareId, readOnly]);
148→
149→  const handleSave = useCallback(async () => {
150→    if (!item || !isDirty) return;
151→
152→    setSaving(true);
153→    setError(null);
154→
155→    try {
156→      if (shareId && onSaveSharedFile) {
157→        // Shared file path: delegate to shared navigation handler
158→        const encoded = new TextEncoder().encode(content);
159→        await onSaveSharedFile(item, encoded);
160→      } else {
161→        // Owner path: encrypt and update folder metadata
162→        const auth = useAuthStore.getState();
163→        if (!auth.vaultKeypair) {
164→          throw new Error('No keypair available - please log in again');
165→        }
166→
167→        const encoded = new TextEncoder().encode(content);
168→        const file = new File([encoded], item.name);
169→        const encrypted = await encryptFile(file, auth.vaultKeypair.publicKey);
170→        const blob = new Blob([encrypted.ciphertext as BlobPart]);
171→        const { cid } = await addToIpfs(blob);
172→
173→        await updateFile(parentFolderId, {
174→          fileId: item.id,
175→          newCid: cid,
176→          newFileKeyEncrypted: encrypted.wrappedKey,
177→          newFileIv: encrypted.iv,
178→          newSize: encrypted.originalSize,
179→        });
180→      }
181→
182→      onClose();
183→    } catch (err) {
184→      setError(err instanceof Error ? err.message : 'Failed to save file');
185→      setSaving(false);
186→    }
187→  }, [item, content, isDirty, parentFolderId, updateFile, onClose, shareId, onSaveSharedFile]);
188→
189→  // Handle Ctrl/Cmd+S to save (edit mode only)
190→  useEffect(() => {
191→    if (!open || readOnly) return;
192→
193→    const handleKeyDown = (e: KeyboardEvent) => {
194→      if ((e.metaKey || e.ctrlKey) && e.key === 's') {
195→        e.preventDefault();
196→        if (isDirty && !saving && !loading) {
197→          handleSave();
198→        }
199→      }
200→    };
201→
202→    document.addEventListener('keydown', handleKeyDown);
203→    return () => document.removeEventListener('keydown', handleKeyDown);
204→  }, [open, readOnly, isDirty, saving, loading, handleSave]);
205→
206→  const handleDownload = useCallback(() => {
207→    if (!item || !content) return;
208→    const encoded = new TextEncoder().encode(content);
209→    triggerBrowserDownload(encoded, item.name, 'text/plain');
210→  }, [item, content]);
211→
212→  if (!item) return null;
213→
214→  const title = readOnly ? `View: ${item.name}` : `Edit: ${item.name}`;
215→  const isDisabled = saving || loading;
216→
217→  return (
218→    <Modal
219→      open={open}
220→      onClose={isDisabled ? undefined : onClose}
221→      title={title}
222→      className="text-editor-modal"
223→    >
224→      {loading ? (
225→        <div className="text-editor-loading">decrypting...</div>
226→      ) : (
227→        <div className="text-editor-body">
228→          <textarea
229→            ref={textareaRef}
230→            className="text-editor-textarea"
231→            value={content}
232→            onChange={readOnly ? undefined : (e) => setContent(e.target.value)}
233→            disabled={isDisabled}
234→            readOnly={readOnly}
235→            spellCheck={false}
236→            aria-label={`Content of ${item.name}`}
237→          />
238→          <div className={`text-editor-status${isDirty ? ' text-editor-status--modified' : ''}`}>
239→            <span>
240→              {'// '}
241→              {lineCount} {lineCount === 1 ? 'line' : 'lines'}
242→              {' | utf-8'}
243→              {readOnly ? ' | read-only' : ''}
244→              {isDirty ? ' | modified' : ''}
245→            </span>
246→          </div>
247→          {error && (
248→            <div className="text-editor-error">
249→              {'> '}
250→              {error}
251→            </div>
252→          )}
253→          <div className="text-editor-footer">
254→            {readOnly ? (
255→              <>
256→                <button
257→                  type="button"
258→                  className="dialog-button dialog-button--secondary"
259→                  onClick={handleDownload}
260→                >
261→                  --download
262→                </button>
263→                <button
264→                  type="button"
265→                  className="dialog-button dialog-button--primary"
266→                  onClick={onClose}
267→                >
268→                  close
269→                </button>
270→              </>
271→            ) : (
272→              <>
273→                <button
274→                  type="button"
275→                  className="dialog-button dialog-button--secondary"
276→                  onClick={onClose}
277→                  disabled={isDisabled}
278→                >
279→                  cancel
280→                </button>
281→                <button
282→                  type="button"
283→                  className="dialog-button dialog-button--primary"
284→                  onClick={handleSave}
285→                  disabled={isDisabled || !isDirty}
286→                >
287→                  {saving ? 'encrypting...' : '--save'}
288→                </button>
289→              </>
290→            )}
291→          </div>
292→        </div>
293→      )}
294→    </Modal>
295→  );
296→}
