  3→/**
  4→ * A received share from another CipherBox user.
  5→ * Contains the ECIES-wrapped item key for decryption.
  6→ */
  7→export type ReceivedShare = {
  8→  shareId: string;
  9→  sharerPublicKey: string;
 10→  itemType: 'folder' | 'file';
 11→  ipnsName: string;
 12→  itemName: string;
 13→  /** Hex-encoded ECIES ciphertext of the item key */
 14→  encryptedKey: string;
 15→  /** Permission level: read-only or read-write */
 16→  permission: 'read' | 'write';
 17→  /** Hex-encoded ECIES ciphertext of IPNS private key (write shares only) */
 18→  encryptedIpnsKey: string | null;
 19→  createdAt: string;
 20→};
 21→
 22→/**
 23→ * A share sent by the current user to another CipherBox user.
 24→ * Does not contain the encrypted key (sharer already has access).
 25→ */
 26→export type SentShare = {
 27→  shareId: string;
 28→  recipientPublicKey: string;
 29→  itemType: 'folder' | 'file';
 30→  ipnsName: string;
 31→  itemName: string;
 32→  /** Permission level: read-only or read-write */
 33→  permission: 'read' | 'write';
 34→  createdAt: string;
 35→};
 36→
 37→type ShareState = {
 38→  receivedShares: ReceivedShare[];
 39→  sentShares: SentShare[];
 40→  isLoadingReceived: boolean;
 41→  isLoadingSent: boolean;
 42→  lastReceivedFetchedAt: number | null;
 43→  lastSentFetchedAt: number | null;
 44→
 45→  // Actions
 46→  setReceivedShares: (shares: ReceivedShare[]) => void;
 47→  setSentShares: (shares: SentShare[]) => void;
 48→  setLoadingReceived: (loading: boolean) => void;
 49→  setLoadingSent: (loading: boolean) => void;
 50→  addSentShare: (share: SentShare) => void;
 51→  removeSentShare: (shareId: string) => void;
 52→  removeReceivedShare: (shareId: string) => void;
 53→  updateSentSharePermission: (shareId: string, permission: 'read' | 'write') => void;
 54→  clearShares: () => void;
 55→};
 56→
 57→/**
 58→ * Share store for managing sent/received share state.
 59→ *
 60→ * Maintains the in-memory lists of shares the user has
 61→ * sent to others and received from others.
 62→ *
 63→ * Call clearShares() on logout to reset state.
 64→ */
 65→export const useShareStore = create<ShareState>((set) => ({
 66→  // State
 67→  receivedShares: [],
 68→  sentShares: [],
 69→  isLoadingReceived: false,
 70→  isLoadingSent: false,
 71→  lastReceivedFetchedAt: null,
 72→  lastSentFetchedAt: null,
 73→
 74→  // Actions
 75→  setReceivedShares: (shares) =>
 76→    set({ receivedShares: shares, isLoadingReceived: false, lastReceivedFetchedAt: Date.now() }),
 77→
 78→  setSentShares: (shares) =>
 79→    set({ sentShares: shares, isLoadingSent: false, lastSentFetchedAt: Date.now() }),
 80→
 81→  setLoadingReceived: (loading) => set({ isLoadingReceived: loading }),
 82→
 83→  setLoadingSent: (loading) => set({ isLoadingSent: loading }),
 84→
 85→  addSentShare: (share) =>
 86→    set((state) => ({
 87→      sentShares: [...state.sentShares, share],
 88→    })),
 89→
 90→  removeSentShare: (shareId) =>
 91→    set((state) => ({
 92→      sentShares: state.sentShares.filter((s) => s.shareId !== shareId),
 93→    })),
 94→
 95→  removeReceivedShare: (shareId) =>
 96→    set((state) => ({
 97→      receivedShares: state.receivedShares.filter((s) => s.shareId !== shareId),
 98→    })),
 99→
100→  updateSentSharePermission: (shareId, permission) =>
101→    set((state) => ({
102→      sentShares: state.sentShares.map((s) => (s.shareId === shareId ? { ...s, permission } : s)),
103→    })),
104→
105→  clearShares: () =>
106→    set({
107→      receivedShares: [],
108→      sentShares: [],
109→      isLoadingReceived: false,
110→      isLoadingSent: false,
111→      lastReceivedFetchedAt: null,
112→      lastSentFetchedAt: null,
113→    }),
114→}));
