 36→ */
 37→export async function fetchReceivedShares(
 38→  limit = 50,
 39→  offset = 0
 40→): Promise<{ shares: ReceivedShare[]; total: number }> {
 41→  const response = await sharesControllerGetReceivedShares({ limit, offset });
 42→
 43→  return {
 44→    shares: response.shares.map((s) => ({
 45→      shareId: s.shareId,
 46→      sharerPublicKey: s.sharerPublicKey,
 47→      itemType: s.itemType as 'folder' | 'file',
 48→      ipnsName: s.ipnsName,
 49→      itemName: s.itemName,
 50→      encryptedKey: s.encryptedKey,
 51→      permission: (s.permission as 'read' | 'write') ?? 'read',
 52→      encryptedIpnsKey: (s.encryptedIpnsKey as string | null | undefined) ?? null,
 53→      createdAt: String(s.createdAt),
 54→    })),
 55→    total: response.total,
 56→  };
 57→}
