102→export async function createShare(params: {
103→  recipientPublicKey: string;
104→  itemType: 'folder' | 'file';
105→  ipnsName: string;
106→  itemName: string;
107→  encryptedKey: string;
108→  childKeys?: Array<{ keyType: 'file' | 'folder'; itemId: string; encryptedKey: string }>;
