184→  keys: Array<{ keyType: 'file' | 'folder' | 'file-ipns'; itemId: string; encryptedKey: string }>
185→): Promise<void> {
186→  await sharesControllerAddShareKeys(shareId, {
187→    keys: keys.map((k) => ({
188→      keyType: k.keyType,
189→      itemId: k.itemId,
