195→/**
196→ * Get sent shares for a specific item (by IPNS name).
197→ * Fetches all sent shares and filters by ipnsName.
198→ * Uses the store cache if available and fresh.
199→ */
200→export async function getSentSharesForItem(ipnsName: string): Promise<SentShare[]> {
201→  const shares = await ensureFreshSentShares();
202→  return shares.filter((s) => s.ipnsName === ipnsName);
