205→// ---------------------------------------------------------------------------
206→// Post-upload / post-create share key propagation
207→// ---------------------------------------------------------------------------
208→
209→/**
210→ * Ensure sent shares cache is fresh (fetched within last 30s).
211→ * Returns the current sent shares array.
212→ */
213→async function ensureFreshSentShares(): Promise<SentShare[]> {
214→  const store = useShareStore.getState();
215→  if (store.lastSentFetchedAt && Date.now() - store.lastSentFetchedAt < 30_000) {
216→    return store.sentShares;
217→  }
218→  // Re-wrapping needs the full set — paginate through all pages
219→  const allShares = await fetchAllSentShares();
220→  useShareStore.getState().setSentShares(allShares);
221→  return allShares;
222→}
223→
224→/**
225→ * Fetch ALL sent shares by paginating through the API.
226→ * The API enforces a max limit of 100 per page.
227→ */
228→async function fetchAllSentShares(): Promise<SentShare[]> {
229→  const pageSize = 100;
230→  let offset = 0;
231→  const allShares: SentShare[] = [];
232→
233→  while (true) {
234→    const { shares, total } = await fetchSentShares(pageSize, offset);
235→    allShares.push(...shares);
236→    offset += shares.length;
237→    if (offset >= total || shares.length === 0) break;
238→  }
239→
240→  return allShares;
241→}
242→
243→/**
244→ * Check if a folder (by IPNS name) has any active shares.
245→ * Used to decide whether post-upload re-wrapping is needed.
246→ */
247→export async function hasActiveShares(folderIpnsName: string): Promise<boolean> {
248→  const shares = await ensureFreshSentShares();
249→  return shares.some((s) => s.ipnsName === folderIpnsName);
250→}
251→
252→/**
253→ * Find active shares that cover a given folder, including ancestor shares.
254→ * A folder is "covered" if it or any of its ancestor folders is shared.
255→ *
256→ * Walks the ancestor chain and checks each folder's IPNS name against sent shares.
257→ *
258→ * @param folderIpnsName - IPNS name of the current folder
259→ * @param folders - Current folder tree from the folder store
260→ * @param currentFolderId - ID of the current folder in the tree
261→ * @returns Array of sent shares covering this folder (may be from ancestor)
262→ */
263→export async function findCoveringShares(
264→  folderIpnsName: string,
265→  folders: Record<string, FolderNode>,
266→  currentFolderId: string | null
267→): Promise<SentShare[]> {
268→  const shares = await ensureFreshSentShares();
269→  if (shares.length === 0) return [];
270→
271→  // Collect all IPNS names from this folder up to root
272→  const ipnsNames = new Set<string>();
273→  ipnsNames.add(folderIpnsName);
274→
275→  let walkId = currentFolderId;
276→  while (walkId) {
277→    const node = folders[walkId];
278→    if (!node) break;
279→    ipnsNames.add(node.ipnsName);
280→    walkId = node.parentId;
281→  }
282→
283→  return shares.filter((s) => ipnsNames.has(s.ipnsName));
284→}
