286→/**
287→ * After adding a file or subfolder to a shared folder, re-wrap the new key
288→ * for all existing share recipients.
289→ *
290→ * This is a fire-and-forget operation -- failures are logged but don't block
291→ * the primary upload/create flow.
292→ *
293→ * IMPORTANT: Callers are responsible for zeroing `newItems[*].plaintextKey`
294→ * after this function completes. This function does NOT zero the keys because
295→ * some callers (e.g., subfolder creation) keep the key alive in the store.
296→ * Use a `finally` block to ensure zeroing even on errors.
297→ *
298→ * @param params.folderIpnsName - IPNS name of the folder being modified
299→ * @param params.folders - Current folder tree from the store
300→ * @param params.currentFolderId - ID of the current folder in the tree
301→ * @param params.newItems - New items whose keys need re-wrapping
302→ */
303→export async function reWrapForRecipients(params: {
304→  folderIpnsName: string;
305→  folders: Record<string, FolderNode>;
306→  currentFolderId: string | null;
307→  newItems: Array<{
308→    keyType: 'file' | 'folder';
309→    itemId: string;
310→    plaintextKey: Uint8Array;
311→  }>;
312→}): Promise<{ failedRecipients: string[] }> {
313→  const coveringShares = await findCoveringShares(
314→    params.folderIpnsName,
315→    params.folders,
316→    params.currentFolderId
317→  );
318→
319→  if (coveringShares.length === 0) return { failedRecipients: [] };
320→
321→  const failedRecipients: string[] = [];
322→
323→  // For each share recipient, re-wrap all new item keys
324→  for (const share of coveringShares) {
325→    try {
326→      const recipientPubKey = hexToBytes(
327→        share.recipientPublicKey.startsWith('0x')
328→          ? share.recipientPublicKey.slice(2)
329→          : share.recipientPublicKey
330→      );
331→
332→      const wrappedKeys: Array<{
333→        keyType: 'file' | 'folder';
334→        itemId: string;
335→        encryptedKey: string;
336→      }> = [];
337→
338→      for (const item of params.newItems) {
339→        const wrapped = await wrapKey(item.plaintextKey, recipientPubKey);
340→        wrappedKeys.push({
341→          keyType: item.keyType,
342→          itemId: item.itemId,
343→          encryptedKey: bytesToHex(wrapped),
344→        });
345→      }
346→
347→      // Add the wrapped keys to this share via API
348→      await addShareKeys(share.shareId, wrappedKeys);
349→    } catch (err) {
350→      console.warn(
351→        `[share] Failed to re-wrap keys for recipient ${share.recipientPublicKey.slice(0, 10)}...:`,
352→        err
353→      );
354→      failedRecipients.push(share.recipientPublicKey);
355→    }
356→  }
357→
358→  return { failedRecipients };
359→}
