361→// ---------------------------------------------------------------------------
362→// Lazy key rotation after revocation
363→// ---------------------------------------------------------------------------
364→
365→/** A revoked share pending key rotation. */
366→export type PendingRotation = {
367→  shareId: string;
368→  recipientPublicKey: string;
369→  itemType: 'folder' | 'file';
370→  ipnsName: string;
371→  itemName: string;
372→  revokedAt: string;
373→};
374→
375→/**
376→ * Fetch revoked shares that are pending key rotation from the server.
377→ * These are shares where revokedAt is set but the share has not been hard-deleted.
378→ */
379→export async function fetchPendingRotations(): Promise<PendingRotation[]> {
380→  const response = await sharesControllerGetPendingRotations();
381→
382→  return response.map((r) => ({
383→    shareId: r.shareId,
384→    recipientPublicKey: r.recipientPublicKey,
385→    itemType: r.itemType as 'folder' | 'file',
386→    ipnsName: r.ipnsName,
387→    itemName: r.itemName,
388→    revokedAt: String(r.revokedAt),
389→  }));
390→}
391→
392→/**
393→ * Check if a folder has pending rotations (revoked shares awaiting key rotation).
394→ * Called before any folder modification.
395→ *
396→ * @param folderIpnsName - IPNS name of the folder being modified
397→ * @returns true if there are revoked shares for this folder that need rotation
398→ */
399→export async function checkPendingRotation(folderIpnsName: string): Promise<boolean> {
400→  const pendingRotations = await fetchPendingRotations();
401→  return pendingRotations.some((r) => r.ipnsName === folderIpnsName);
402→}
403→
404→/**
405→ * Update the encrypted key on a share record after lazy key rotation.
406→ * Re-wraps the new folder key for a remaining (non-revoked) recipient.
407→ */
408→export async function updateShareKey(shareId: string, encryptedKey: string): Promise<void> {
409→  await sharesControllerUpdateShareEncryptedKey(shareId, { encryptedKey });
410→}
411→
412→/**
413→ * Hard-delete a revoked share after rotation is complete.
414→ */
415→export async function completeShareRotation(shareId: string): Promise<void> {
416→  await sharesControllerCompleteRotation(shareId);
417→}
418→
419→/**
420→ * Execute lazy key rotation for a folder.
421→ * Called when a folder modification is about to happen and pending rotations exist.
422→ *
423→ * Protocol:
424→ * 1. Generate new random folderKey
425→ * 2. Re-wrap new folderKey for each REMAINING (non-revoked) active recipient
426→ * 3. Update remaining shares with the new encrypted key
427→ * 4. Hard-delete revoked share records (rotation complete)
428→ * 5. Invalidate share cache
429→ *
430→ * NOTE: The actual folder metadata re-encryption (decrypt with old key, re-encrypt
431→ * with new key, re-publish IPNS) is handled by the caller (folder.service.ts)
432→ * since it has access to the folder's IPNS private key and publishing infrastructure.
433→ *
434→ * @returns The new folderKey for the caller to use
435→ */
436→export async function executeLazyRotation(params: {
437→  folderIpnsName: string;
438→  oldFolderKey: Uint8Array;
439→  ownerPublicKey: Uint8Array;
440→}): Promise<{ newFolderKey: Uint8Array }> {
441→  // 1. Generate new random 32-byte folderKey
442→  const newFolderKey = generateRandomBytes(32);
443→
444→  // 2. Fetch pending rotations and active shares for this folder
445→  const [pendingRotations, activeSentShares] = await Promise.all([
446→    fetchPendingRotations(),
447→    getSentSharesForItem(params.folderIpnsName),
448→  ]);
449→
450→  const revokedForFolder = pendingRotations.filter((r) => r.ipnsName === params.folderIpnsName);
451→  const revokedShareIds = new Set(revokedForFolder.map((r) => r.shareId));
452→
453→  // Active shares that are NOT revoked -- these recipients keep access
454→  const remainingShares = activeSentShares.filter((s) => !revokedShareIds.has(s.shareId));
455→
456→  // 3. Re-wrap new folderKey for each remaining recipient
457→  const reWrapFailures: string[] = [];
458→  for (const share of remainingShares) {
459→    try {
460→      const recipientPubKey = hexToBytes(
461→        share.recipientPublicKey.startsWith('0x')
462→          ? share.recipientPublicKey.slice(2)
463→          : share.recipientPublicKey
464→      );
465→      const wrapped = await wrapKey(newFolderKey, recipientPubKey);
466→      await updateShareKey(share.shareId, bytesToHex(wrapped));
467→    } catch (err) {
468→      console.warn(
469→        `[share] Failed to update share key for remaining recipient ${share.recipientPublicKey.slice(0, 10)}...:`,
470→        err
471→      );
472→      reWrapFailures.push(share.shareId);
473→    }
474→  }
475→
476→  if (reWrapFailures.length > 0) {
477→    newFolderKey.fill(0);
478→    throw new Error(
479→      `Key rotation failed: could not re-wrap key for ${reWrapFailures.length} recipient(s). ` +
480→        'Aborting to prevent inconsistent state.'
481→    );
482→  }
483→
484→  // 4. Hard-delete all revoked shares for this folder
485→  for (const revoked of revokedForFolder) {
486→    try {
487→      await completeShareRotation(revoked.shareId);
488→    } catch (err) {
489→      console.warn(`[share] Failed to complete rotation for share ${revoked.shareId}:`, err);
490→    }
491→  }
492→
493→  // 5. Invalidate the sent shares cache so next check fetches fresh state
494→  useShareStore.getState().setSentShares([]);
495→
496→  return { newFolderKey };
497→}
