 44→} from '../services/share.service';
 45→import {
 46→  resolveIpnsRecord,
 47→  createAndPublishIpnsRecord,
 48→  batchPublishIpnsRecords,
 49→} from '../services/ipns.service';
 50→import { fetchFromIpfs, addToIpfs } from '../lib/api/ipfs';
 51→import { downloadFile, triggerBrowserDownload } from '../services/download.service';
 52→import { useDownloadStore } from '../stores/download.store';
 53→import { withConflictRetry } from './folder-helpers';
 54→
 55→/**
 56→ * Breadcrumb entry for shared navigation.
 57→ */
 58→export type SharedBreadcrumb = {
 59→  id: string;
 60→  name: string;
