122→/**
123→ * Hook for browsing shared content.
124→ *
125→ * Manages the "Shared with me" browsing experience.
126→ * Top-level view shows received shares as a flat list.
127→ * Clicking a shared folder navigates into it using re-wrapped keys.
128→ *
129→ * For write shares, also provides write operation handlers and 30s polling.
130→ */
131→export function useSharedNavigation(): UseSharedNavigationReturn {
132→  const [currentView, setCurrentView] = useState<SharedView>('list');
133→  const [currentShareId, setCurrentShareId] = useState<string | null>(null);
134→  const [sharedItems, setSharedItems] = useState<SharedListItem[]>([]);
135→  const [folderChildren, setFolderChildren] = useState<FolderChild[]>([]);
136→  const [folderKey, setFolderKey] = useState<Uint8Array | null>(null);
137→  const [breadcrumbs, setBreadcrumbs] = useState<SharedBreadcrumb[]>([]);
138→  const [isLoading, setIsLoading] = useState(true);
139→  const [error, setError] = useState<string | null>(null);
140→  const [permission, setPermission] = useState<'read' | 'write' | null>(null);
141→  const [ipnsName, setIpnsName] = useState<string | null>(null);
142→  const [currentSequenceNumber, setCurrentSequenceNumber] = useState<bigint | null>(null);
143→
144→  // IPNS private key stored in ref to avoid re-renders; zeroed on cleanup
145→  const ipnsPrivateKeyRef = useRef<Uint8Array | null>(null);
146→
147→  // Navigation stack for folder browsing within a share
148→  const navStackRef = useRef<
149→    Array<{
150→      folderId: string;
151→      folderName: string;
152→      children: FolderChild[];
153→      folderKey: Uint8Array;
154→      ipnsName: string;
155→      sequenceNumber: bigint | null;
156→    }>
157→  >([]);
158→
159→  // Cache share keys per shareId with TTL to avoid refetching
160→  const shareKeysCache = useRef<
161→    Map<
162→      string,
163→      {
164→        keys: Array<{
165→          keyType: 'file' | 'folder' | 'file-ipns';
166→          itemId: string;
167→          encryptedKey: string;
168→        }>;
169→        fetchedAt: number;
170→      }
171→    >
172→  >(new Map());
173→
174→  // Polling interval ref for 30s sync
175→  const pollIntervalRef = useRef<ReturnType<typeof setInterval> | null>(null);
176→
177→  /**
178→   * Zero the IPNS private key and clear the ref.
179→   */
180→  const zeroIpnsKey = useCallback(() => {
181→    if (ipnsPrivateKeyRef.current) {
182→      ipnsPrivateKeyRef.current.fill(0);
183→      ipnsPrivateKeyRef.current = null;
184→    }
185→  }, []);
186→
187→  /**
188→   * Clear polling interval.
189→   */
190→  const clearPolling = useCallback(() => {
191→    if (pollIntervalRef.current) {
192→      clearInterval(pollIntervalRef.current);
193→      pollIntervalRef.current = null;
194→    }
195→  }, []);
196→
197→  /**
198→   * Handle silent revocation: transition from write to read-only.
199→   */
200→  const handleRevocation = useCallback(
201→    (showError?: boolean) => {
202→      zeroIpnsKey();
203→      setPermission('read');
204→      if (showError) {
205→        setError('> write access revoked -- folder is now read-only');
206→      }
207→    },
208→    [zeroIpnsKey]
209→  );
210→
211→  /**
212→   * Refresh folder contents from IPNS (used by polling and after write ops).
213→   * Returns the refreshed children, or null on failure.
214→   */
215→  const refreshFolderContents = useCallback(
216→    async (folderIpnsName: string, currentFolderKey: Uint8Array): Promise<FolderChild[] | null> => {
217→      try {
218→        const resolved = await resolveIpnsRecord(folderIpnsName);
219→        if (!resolved) return null;
220→
221→        const encryptedBytes = await fetchFromIpfs(resolved.cid);
222→        const encryptedJson = new TextDecoder().decode(encryptedBytes);
223→        const encrypted: EncryptedFolderMetadata = JSON.parse(encryptedJson);
224→        const metadata = await decryptFolderMetadata(encrypted, currentFolderKey);
225→
226→        setFolderChildren(metadata.children ?? []);
227→        setCurrentSequenceNumber(resolved.sequenceNumber);
228→        return metadata.children ?? [];
229→      } catch {
230→        return null;
231→      }
232→    },
233→    []
234→  );
235→
236→  /**
237→   * Load received shares on mount.
238→   */
239→  useEffect(() => {
240→    let cancelled = false;
241→
242→    async function loadShares() {
243→      setIsLoading(true);
244→      setError(null);
245→
246→      try {
247→        // Paginate through all received shares (API max 100 per page)
248→        const pageSize = 100;
249→        let offset = 0;
250→        const shares: ReceivedShare[] = [];

250→        const shares: ReceivedShare[] = [];
251→
252→        while (true) {
253→          const page = await fetchReceivedShares(pageSize, offset);
254→          if (cancelled) return;
255→          shares.push(...page.shares);
256→          offset += page.shares.length;
257→          if (offset >= page.total || page.shares.length === 0) break;
258→        }
259→
260→        useShareStore.getState().setReceivedShares(shares);
261→
262→        const items: SharedListItem[] = shares.map((share) => ({
263→          share,
264→          children: null,
265→          folderKey: null,
266→        }));
267→
268→        setSharedItems(items);
269→      } catch (err) {
270→        if (cancelled) return;
271→        console.error('Failed to load shared items:', err);
272→        setError('Failed to load shared items');
273→      } finally {
274→        if (!cancelled) {
275→          setIsLoading(false);
276→        }
277→      }
278→    }
279→
280→    loadShares();
281→    return () => {
282→      cancelled = true;
283→      // Zero all decrypted folder keys on unmount
284→      setFolderKey((prev) => {
285→        if (prev) prev.fill(0);
286→        return null;
287→      });
288→      for (const entry of navStackRef.current) {
289→        entry.folderKey.fill(0);
290→      }
291→      navStackRef.current = [];
292→      // Zero IPNS private key on unmount
293→      zeroIpnsKey();
294→      // Clear polling on unmount
295→      clearPolling();
296→    };
297→  }, [zeroIpnsKey, clearPolling]);
298→
299→  /** Cache TTL for share keys (60 seconds). */
300→  const SHARE_KEYS_CACHE_TTL = 60_000;
301→
302→  /**
303→   * Get share keys for a share, with TTL-based caching.
304→   */
305→  const getShareKeys = useCallback(async (shareId: string) => {
306→    const cached = shareKeysCache.current.get(shareId);
307→    if (cached && Date.now() - cached.fetchedAt < SHARE_KEYS_CACHE_TTL) {
308→      return cached.keys;
309→    }
310→
311→    const keys = await fetchShareKeys(shareId);
312→    shareKeysCache.current.set(shareId, { keys, fetchedAt: Date.now() });
313→    return keys;
314→  }, []);
315→
316→  /**
317→   * Navigate into a shared folder from the top-level list.
318→   */
319→  const navigateToShare = useCallback(
320→    async (shareId: string) => {
321→      const auth = useAuthStore.getState();
322→      if (!auth.vaultKeypair) {
323→        setError('No keypair available');
324→        return;
325→      }
326→
327→      const shareItem = sharedItems.find((s) => s.share.shareId === shareId);
328→      if (!shareItem) return;
329→
330→      const share = shareItem.share;
331→
332→      setIsLoading(true);
333→      setError(null);
334→      clearPolling();
335→
336→      try {
337→        // Unwrap the shared item's key with our private key
338→        const itemKey = await unwrapKey(
339→          hexToBytes(share.encryptedKey),
340→          auth.vaultKeypair.privateKey
341→        );
342→
343→        if (share.itemType === 'folder') {
344→          let folderKeyStored = false;
345→          try {
346→            // Resolve folder IPNS to get metadata
347→            const resolved = await resolveIpnsRecord(share.ipnsName);
348→            if (!resolved) {
349→              throw new Error('Could not resolve shared folder IPNS');
350→            }
351→
352→            // Fetch and decrypt folder metadata
353→            const encryptedBytes = await fetchFromIpfs(resolved.cid);
354→            const encryptedJson = new TextDecoder().decode(encryptedBytes);
355→            const encrypted: EncryptedFolderMetadata = JSON.parse(encryptedJson);
356→            const metadata = await decryptFolderMetadata(encrypted, itemKey);
357→
358→            // Unwrap IPNS private key for write shares
359→            if (share.permission === 'write' && share.encryptedIpnsKey) {
360→              try {
361→                const ipnsPrivKey = await unwrapKey(
362→                  hexToBytes(share.encryptedIpnsKey),
363→                  auth.vaultKeypair.privateKey
364→                );
365→                ipnsPrivateKeyRef.current = ipnsPrivKey;
366→              } catch (err) {
367→                console.error('Failed to unwrap IPNS key for write share:', err);
368→                // Fall back to read-only if IPNS key unwrap fails
369→              }
370→            }
371→
372→            // Set folder state
373→            setCurrentView('folder');
374→            setCurrentShareId(shareId);
375→            setFolderChildren(metadata.children ?? []);
376→            setFolderKey(itemKey);
377→            folderKeyStored = true;
378→            setBreadcrumbs([{ id: shareId, name: share.itemName }]);
379→            setPermission(ipnsPrivateKeyRef.current ? share.permission : 'read');
380→            setIpnsName(share.ipnsName);
381→            setCurrentSequenceNumber(resolved.sequenceNumber);
382→            navStackRef.current = [];
383→          } finally {
384→            if (!folderKeyStored) itemKey.fill(0);
385→          }
386→        } else {
387→          // For files, trigger download directly
388→          // itemKey is the parent folder key; downloadSharedFileFromShare unwraps its own copy
389→          itemKey.fill(0);
390→          await downloadSharedFileFromShare(share, auth.vaultKeypair.privateKey);
391→        }
392→      } catch (err) {
393→        console.error('Failed to navigate to shared item:', err);
394→        setError('Failed to open shared item');
395→      } finally {
396→        setIsLoading(false);
397→      }
398→    },
399→    [sharedItems, clearPolling]
400→  );
