493→  /**
494→   * Navigate back to the top-level shared list.
495→   * Zeroes all decrypted folder keys from memory before clearing state.
496→   */
497→  const navigateToRoot = useCallback(() => {
498→    // Zero current folder key
499→    if (folderKey) folderKey.fill(0);

500→    // Zero all nav stack folder keys
501→    for (const entry of navStackRef.current) {
502→      entry.folderKey.fill(0);
503→    }
504→    // Zero IPNS private key
505→    zeroIpnsKey();
506→    // Clear polling
507→    clearPolling();
508→    setCurrentView('list');
509→    setCurrentShareId(null);
510→    setFolderChildren([]);
511→    setFolderKey(null);
512→    setBreadcrumbs([]);
513→    setPermission(null);
514→    setIpnsName(null);
515→    setCurrentSequenceNumber(null);
516→    navStackRef.current = [];
517→    setError(null);
