520→  /**
521→   * Navigate up one level.
522→   */
523→  const navigateUp = useCallback(() => {
524→    if (navStackRef.current.length > 0) {
525→      // Zero current folder key before replacing
526→      if (folderKey) folderKey.fill(0);
527→      // Pop from nav stack
528→      const prev = navStackRef.current.pop()!;
529→      setFolderChildren(prev.children);
530→      setFolderKey(prev.folderKey);
531→      setBreadcrumbs((crumbs) => crumbs.slice(0, -1));
532→      setIpnsName(prev.ipnsName);
533→      setCurrentSequenceNumber(prev.sequenceNumber);
534→    } else if (currentView === 'folder') {
535→      // Back to top-level list
536→      navigateToRoot();
537→    }
538→  }, [currentView, folderKey, navigateToRoot]);
