540→  /**
541→   * Navigate directly to a breadcrumb level, zeroing all intermediate keys.
542→   * More efficient than calling navigateUp() in a loop.
543→   */
544→  const navigateToBreadcrumb = useCallback(
545→    (crumbIndex: number) => {
546→      const popsNeeded = breadcrumbs.length - 1 - crumbIndex;
547→      if (popsNeeded <= 0) return;
548→      // Zero the current folder key
549→      if (folderKey) folderKey.fill(0);
550→      // Zero and discard all intermediate keys
551→      for (let i = 0; i < popsNeeded - 1; i++) {
552→        const entry = navStackRef.current.pop();
553→        if (entry) entry.folderKey.fill(0);
554→      }
555→      // Restore the target level
556→      const target = navStackRef.current.pop();
557→      if (target) {
558→        setFolderChildren(target.children);
559→        setFolderKey(target.folderKey);
560→        setBreadcrumbs((crumbs) => crumbs.slice(0, crumbIndex + 1));
561→        setIpnsName(target.ipnsName);
562→        setCurrentSequenceNumber(target.sequenceNumber);
563→      }
564→    },
565→    [breadcrumbs, folderKey]
566→  );
