568→  /**
569→   * Download a shared file from the top-level list.
570→   * The share's encryptedKey wraps the parent folder key (needed to decrypt file metadata).
571→   * The actual file key is stored as a child key in share_keys.
572→   */
573→  async function downloadSharedFileFromShare(
574→    share: ReceivedShare,
575→    privateKey: Uint8Array
576→  ): Promise<void> {
577→    if (share.itemType !== 'file') return;
578→
579→    const downloadStore = useDownloadStore.getState();
580→
581→    try {
582→      downloadStore.startDownload(share.itemName);
583→
584→      // Unwrap the parent folder key from the share record
585→      const parentFolderKey = await unwrapKey(hexToBytes(share.encryptedKey), privateKey);
586→
587→      let fileMeta: Awaited<ReturnType<typeof decryptFileMetadata>>;
588→      try {
589→        // Resolve file IPNS metadata and decrypt with parent folder key
590→        const resolved = await resolveIpnsRecord(share.ipnsName);
591→        if (!resolved) {
592→          throw new Error('File metadata IPNS not found');
593→        }
594→
595→        const encryptedBytes = await fetchFromIpfs(resolved.cid);
596→        const encryptedJson = new TextDecoder().decode(encryptedBytes);
597→        const encrypted: EncryptedFileMetadata = JSON.parse(encryptedJson);
598→        fileMeta = await decryptFileMetadata(encrypted, parentFolderKey);
599→      } finally {
600→        parentFolderKey.fill(0);
601→      }
602→
603→      // Get the re-wrapped file key from share_keys
604→      const keys = await fetchShareKeys(share.shareId);
605→      const fileKeyRecord = keys.find((k) => k.keyType === 'file');
606→      if (!fileKeyRecord) {
607→        throw new Error('No re-wrapped file key available for this file');
608→      }
609→
610→      // Download and decrypt using the re-wrapped file key
611→      const plaintext = await downloadFile(
612→        {
613→          cid: fileMeta.cid,
614→          iv: fileMeta.fileIv,
615→          wrappedKey: fileKeyRecord.encryptedKey,
616→          originalName: share.itemName,
617→          encryptionMode: fileMeta.encryptionMode,
618→        },
619→        privateKey
620→      );
621→
622→      downloadStore.setDecrypting();
623→      triggerBrowserDownload(plaintext, share.itemName);
624→      downloadStore.setSuccess();
625→    } catch (err) {
626→      const message = (err as Error).message || 'Download failed';
627→      downloadStore.setError(message);
628→      console.error('Shared file download failed:', err);
629→    }
630→  }
631→
632→  /**
633→   * Download a shared file from within a shared folder.
634→   * Uses re-wrapped file keys from share_keys.
635→   */
636→  const downloadSharedFile = useCallback(
637→    async (item: FilePointer) => {
638→      const auth = useAuthStore.getState();
639→      if (!auth.vaultKeypair || !currentShareId || !folderKey) return;
640→
641→      const downloadStore = useDownloadStore.getState();
642→
643→      try {
644→        downloadStore.startDownload(item.name);
645→
646→        // Get share keys for file key lookup
647→        const keys = await getShareKeys(currentShareId);
648→
649→        // First resolve the file metadata using the parent folder key
650→        const resolved = await resolveIpnsRecord(item.fileMetaIpnsName);
651→        if (!resolved) {
652→          throw new Error('File metadata IPNS not found');
653→        }
654→
655→        const encryptedBytes = await fetchFromIpfs(resolved.cid);
656→        const encryptedJson = new TextDecoder().decode(encryptedBytes);
657→        const encrypted: EncryptedFileMetadata = JSON.parse(encryptedJson);
658→        const fileMeta = await decryptFileMetadata(encrypted, folderKey);
659→
660→        // Look for a re-wrapped file key in share_keys,
661→        // falling back to fileKeyEncrypted from metadata (for files uploaded by current user)
662→        const fileKeyRecord = keys.find((k) => k.keyType === 'file' && k.itemId === item.id);
663→        const wrappedKey = fileKeyRecord?.encryptedKey ?? fileMeta.fileKeyEncrypted;
664→
665→        // downloadFile handles unwrapping internally via wrappedKey + privateKey
666→        const plaintext = await downloadFile(
667→          {
668→            cid: fileMeta.cid,
669→            iv: fileMeta.fileIv,
670→            wrappedKey,
671→            originalName: item.name,
672→            encryptionMode: fileMeta.encryptionMode,
673→          },
674→          auth.vaultKeypair.privateKey
675→        );
676→
677→        downloadStore.setDecrypting();
678→        triggerBrowserDownload(plaintext, item.name);
679→        downloadStore.setSuccess();
680→      } catch (err) {
681→        const message = (err as Error).message || 'Download failed';
682→        downloadStore.setError(message);
683→        console.error('Shared file download failed:', err);
684→      }
685→    },
686→    [currentShareId, folderKey, getShareKeys]
687→  );
