716→  /**
717→   * Publish updated folder metadata to IPNS using the write-share IPNS key.
718→   * Returns the new sequence number on success.
719→   */
720→  const publishSharedFolderMetadata = useCallback(
721→    async (
722→      children: FolderChild[],
723→      currentFolderKey: Uint8Array,
724→      folderIpnsName: string,
725→      ipnsPrivKey: Uint8Array,
726→      seqNum: bigint
727→    ): Promise<bigint> => {
728→      // 1. Create folder metadata
729→      const metadata: FolderMetadata = {
730→        version: 'v2',
731→        children,
732→      };
733→
734→      // 2. Encrypt metadata with folder key
735→      const encrypted = await encryptFolderMetadata(metadata, currentFolderKey);
736→
737→      // 3. Upload to IPFS via backend relay
738→      const blob = new Blob([JSON.stringify(encrypted)], {
739→        type: 'application/json',
740→      });
741→      const { cid } = await addToIpfs(blob);
742→
743→      // 4. Publish IPNS record
744→      const newSeq = seqNum + 1n;
745→      await createAndPublishIpnsRecord({
746→        ipnsPrivateKey: ipnsPrivKey,
747→        ipnsName: folderIpnsName,
748→        metadataCid: cid,
749→        sequenceNumber: newSeq,
750→        expectedSequenceNumber: seqNum.toString(),
751→      });
752→
753→      return newSeq;
754→    },
755→    []
756→  );
