758→  /**
759→   * Wrap a write operation with 403 revocation detection.
760→   * If 403 is received, transitions to read-only silently.
761→   */
762→  const withRevocationGuard = useCallback(
763→    async <T>(operation: () => Promise<T>): Promise<T> => {
764→      try {
765→        return await operation();
766→      } catch (err) {
767→        if (isForbiddenError(err)) {
768→          handleRevocation(true);
769→          throw new Error('> write access revoked -- folder is now read-only');
770→        }
771→        throw err;
772→      }
773→    },
774→    [handleRevocation]
775→  );
