777→  /**
778→   * Upload a file to the currently-viewed write-shared folder.
779→   * Creates a proper per-file IPNS metadata record (same as owner uploads).
780→   */
781→  const uploadFileHandler = useCallback(
782→    async (file: File) => {
783→      const currentIpnsKey = ipnsPrivateKeyRef.current;
784→      const currentFolderKey = folderKey;
785→      const currentIpnsName = ipnsName;
786→      const seqNum = currentSequenceNumber;
787→
788→      if (!currentIpnsKey || !currentFolderKey || !currentIpnsName || seqNum === null) {
789→        setError('Write access not available');
790→        return;
791→      }
792→
793→      const auth = useAuthStore.getState();
794→      if (!auth.vaultKeypair) {
795→        setError('No keypair available');
796→        return;
797→      }
798→
799→      // Get the owner's public key from the share record

 800→      const shareItem = sharedItems.find((s) => s.share.shareId === currentShareId);
 801→      if (!shareItem) {
 802→        setError('Share not found');
 803→        return;
 804→      }
 805→      const ownerPubKeyHex = shareItem.share.sharerPublicKey.startsWith('0x')
 806→        ? shareItem.share.sharerPublicKey.slice(2)
 807→        : shareItem.share.sharerPublicKey;
 808→      const ownerPublicKey = hexToBytes(ownerPubKeyHex);
 809→
 810→      setIsLoading(true);
 811→      setError(null);
 812→
 813→      try {
 814→        await withRevocationGuard(async () => {
 815→          // Read file content
 816→          const data = new Uint8Array(await file.arrayBuffer());
 817→
 818→          // Encrypt file content with AES-256-GCM
 819→          const { encryptAesGcm, generateFileKey, generateIv } = await import('@cipherbox/crypto');
 820→
 821→          const fileKey = generateFileKey();
 822→          const iv = generateIv();
 823→
 824→          try {
 825→            const ciphertext = await encryptAesGcm(data, fileKey, iv);
 826→
 827→            // Upload encrypted content to IPFS
 828→            const fileBlob = new Blob([new Uint8Array(ciphertext)], {
 829→              type: 'application/octet-stream',
 830→            });
 831→            const { cid: contentCid } = await addToIpfs(fileBlob);
 832→
 833→            // Wrap file key with owner's public key for file metadata
 834→            const ownerWrappedKey = await wrapKey(fileKey, ownerPublicKey);
 835→            const fileKeyEncrypted = bytesToHex(ownerWrappedKey);
 836→
 837→            // Generate IPNS keypair for this file's metadata record
 838→            // Inline instead of using createFileMetadata so we can wrap with both keys
 839→            const fileId = crypto.randomUUID();
 840→            const mimeType = file.type || 'application/octet-stream';
 841→            const ipnsKeypair = await generateFileIpnsKeypair();
 842→
 843→            try {
 844→              // Wrap IPNS private key with owner's key (stored in FilePointer — owner can update)
 845→              const ownerWrappedIpnsKey = await wrapKey(ipnsKeypair.privateKey, ownerPublicKey);
 846→              const ipnsPrivateKeyEncrypted = bytesToHex(ownerWrappedIpnsKey);
 847→
 848→              // Wrap IPNS private key with recipient's key (stored in share_keys — recipient can update)
 849→              const recipientWrappedIpnsKey = await wrapKey(
 850→                ipnsKeypair.privateKey,
 851→                auth.vaultKeypair!.publicKey
 852→              );
 853→
 854→              // Create and encrypt file metadata
 855→              const now = Date.now();
 856→              const fileMeta: FileMetadata = {
 857→                version: 'v1',
 858→                cid: contentCid,
 859→                fileKeyEncrypted,
 860→                fileIv: bytesToHex(iv),
 861→                size: data.length,
 862→                mimeType,
 863→                encryptionMode: 'GCM',
 864→                createdAt: now,
 865→                modifiedAt: now,
 866→              };
 867→              const encrypted = await encryptFileMetadata(fileMeta, currentFolderKey);
 868→
 869→              // Upload encrypted metadata to IPFS
 870→              const metaBlob = new Blob([JSON.stringify(encrypted)], { type: 'application/json' });
 871→              const { cid: metadataCid } = await addToIpfs(metaBlob);
 872→
 873→              // Create and publish IPNS record
 874→              const ipnsLifetimeMs = 24 * 60 * 60 * 1000;
 875→              const record = await createIpnsRecord(
 876→                ipnsKeypair.privateKey,
 877→                `/ipfs/${metadataCid}`,
 878→                1n,
 879→                ipnsLifetimeMs
 880→              );
 881→              const recordBytes = marshalIpnsRecord(record);
 882→              let binary = '';
 883→              for (let i = 0; i < recordBytes.length; i++) {
 884→                binary += String.fromCharCode(recordBytes[i]);
 885→              }
 886→              const recordBase64 = btoa(binary);
 887→
 888→              await batchPublishIpnsRecords([
 889→                {
 890→                  ipnsName: ipnsKeypair.ipnsName,
 891→                  recordBase64,
 892→                  metadataCid,
 893→                  recordType: 'file' as const,
 894→                },
 895→              ]);
 896→
 897→              // Create FilePointer with owner-wrapped IPNS key
 898→              const filePointer: FilePointer = {
 899→                type: 'file',
 900→                id: fileId,
 901→                name: file.name,
 902→                fileMetaIpnsName: ipnsKeypair.ipnsName,
 903→                ipnsPrivateKeyEncrypted,
 904→                createdAt: now,
 905→                modifiedAt: now,
 906→              };
 907→
 908→              // Add file to folder metadata with conflict retry
 909→              await withConflictRetry(
 910→                async () => {
 911→                  const freshChildren = [...folderChildren, filePointer];
 912→                  const newSeq = await publishSharedFolderMetadata(
 913→                    freshChildren,
 914→                    currentFolderKey,
 915→                    currentIpnsName,
 916→                    currentIpnsKey,
 917→                    currentSequenceNumber ?? 0n
 918→                  );
 919→                  setCurrentSequenceNumber(newSeq);
 920→                  setFolderChildren(freshChildren);
 921→                },
 922→                async () => {
 923→                  await resyncSharedFolder();
 924→                }
 925→              );
 926→
 927→              // Add share_keys for the recipient:
 928→              // 1. File key (for reading/downloading)
 929→              // 2. IPNS private key (for updating file content)
 930→              const recipientWrappedFileKey = await wrapKey(fileKey, auth.vaultKeypair!.publicKey);
 931→              await addShareKeys(currentShareId!, [
 932→                {
 933→                  keyType: 'file',
 934→                  itemId: fileId,
 935→                  encryptedKey: bytesToHex(recipientWrappedFileKey),
 936→                },
 937→                {
 938→                  keyType: 'file-ipns',
 939→                  itemId: fileId,
 940→                  encryptedKey: bytesToHex(recipientWrappedIpnsKey),
 941→                },
 942→              ]).catch((err) => {
 943→                console.warn('[share] Failed to add share_key for uploaded file:', err);
 944→              });
 945→            } finally {
 946→              ipnsKeypair.privateKey.fill(0);
 947→            }
 948→          } finally {
 949→            fileKey.fill(0);
 950→          }
 951→        });
 952→      } catch (err) {
 953→        const message = (err as Error).message || 'Upload failed';
 954→        if (!message.includes('write access revoked')) {
 955→          setError(message);
 956→        }
 957→        console.error('Shared folder upload failed:', err);
 958→      } finally {
 959→        setIsLoading(false);
 960→      }
 961→    },
 962→    [
 963→      folderKey,
 964→      ipnsName,
 965→      currentSequenceNumber,
 966→      currentShareId,
 967→      folderChildren,
 968→      sharedItems,
 969→      publishSharedFolderMetadata,
 970→      resyncSharedFolder,
 971→      withRevocationGuard,
 972→    ]
 973→  );
 974→
 975→  /**
 976→   * Create a subfolder in the currently-viewed write-shared folder.
 977→   */
 978→  const createFolderHandler = useCallback(
 979→    async (name: string) => {
