129→    let totalFailed = 0;
130→
131→    const CONCURRENCY = 10;
132→
133→    // Process records in batches of CONCURRENCY, delegating to publishRecord
134→    for (let i = 0; i < dto.records.length; i += CONCURRENCY) {
135→      const batch = dto.records.slice(i, i + CONCURRENCY);
136→
137→      const settled = await Promise.allSettled(
138→        batch.map((entry) => this.publishRecord(userId, entry, entry.recordType ?? 'folder'))
139→      );
140→
141→      for (let j = 0; j < settled.length; j++) {
142→        const result = settled[j];
143→        if (result.status === 'fulfilled') {
144→          results.push(result.value);
145→          totalSucceeded++;
146→        } else {
147→          const reason = result.reason;
148→          // If any record (especially a folder record) has a conflict, fail the entire batch
149→          if (reason instanceof ConflictException) {
