308→  /**
309→   * Resolve an IPNS name to its current CID via delegated routing,
310→   * falling back to the DB-cached CID when delegated routing is unavailable
311→   * or when the record is not found in the DHT.
312→   * Returns null if the IPNS name is not found anywhere (404)
313→   */
314→  async resolveRecord(ipnsName: string): Promise<{
315→    cid: string;
316→    sequenceNumber: string;
317→    signatureV2?: string;
318→    data?: string;
319→    pubKey?: string;
320→  } | null> {
321→    const endTimer = this.metricsService.ipfsIpnsDuration.startTimer({
322→      operation: 'resolve',
323→    });
324→    let timerResult = 'success';
325→    let timerSource = 'network';
326→    const startTime = process.hrtime.bigint();
327→    let source = 'network';
328→    let resolveFound = false;
329→
330→    try {
331→      let result: {
332→        cid: string;
333→        sequenceNumber: string;
334→        signatureV2?: string;
335→        data?: string;
336→        pubKey?: string;
337→      } | null = null;
338→
339→      try {
340→        const recordBytes = await this.delegatedRouting.resolve(ipnsName);
341→        if (recordBytes) {
342→          result = this.parseIpnsRecordBytes(recordBytes);
343→          this.logger.debug(`IPNS name resolved successfully: ${ipnsName} -> ${result.cid}`);
344→        }
345→      } catch (error) {
346→        // Fall back to DB cache on BAD_GATEWAY (delegated routing failures)
347→        if (error instanceof HttpException && error.getStatus() === HttpStatus.BAD_GATEWAY) {
348→          this.logger.warn(`Delegated routing failed for ${ipnsName}, falling back to DB cache`);
349→          timerResult = 'error';
350→          source = 'db_cache';
351→        } else {
352→          timerResult = 'error';
353→          throw error;
354→        }
355→      }
356→
357→      // Always check DB cache — it's written synchronously during publish
358→      // and may be ahead of the network (delegated routing can serve stale records)
359→      const cached = await this.folderIpnsRepository.findOne({
360→        where: { ipnsName },
361→      });
362→
363→      if (result && cached?.latestCid) {
364→        // Both sources available — prefer the one with the higher sequence number
365→        const networkSeq = BigInt(result.sequenceNumber);
366→        const dbSeq = BigInt(cached.sequenceNumber);
367→        if (dbSeq > networkSeq) {
368→          this.logger.log(
369→            `DB cache has newer sequence (${dbSeq} > ${networkSeq}) for ${ipnsName}, using DB: ${cached.latestCid}`
370→          );
371→          timerSource = 'db';
372→          source = 'network_stale';
373→          resolveFound = true;
374→          return { cid: cached.latestCid, sequenceNumber: cached.sequenceNumber };
375→        }
376→        timerSource = 'network';
377→        resolveFound = true;
378→        return result;
379→      }
380→
381→      if (result) {
382→        timerSource = 'network';
383→        resolveFound = true;
384→        return result;
385→      }
386→
387→      // Delegated routing returned null (404) or threw BAD_GATEWAY — try DB cache
388→      if (cached?.latestCid) {
389→        this.logger.log(`Resolved ${ipnsName} from DB cache: ${cached.latestCid}`);
390→        timerSource = 'db';
391→        source = 'db_cache';
392→        resolveFound = true;
393→        return { cid: cached.latestCid, sequenceNumber: cached.sequenceNumber };
394→      }
395→
396→      return null;
397→    } catch (error) {
398→      timerResult = 'error';
399→      throw error;
400→    } finally {
401→      endTimer({ result: timerResult, source: timerSource });
402→      if (resolveFound) {
403→        const elapsed = Number(process.hrtime.bigint() - startTime) / 1e9;
404→        this.metricsService.ipnsResolveDuration.observe({ source, outcome: timerResult }, elapsed);
405→      }
406→    }
407→  }
