409→  /**
410→   * Parse an IPNS record to extract CID and sequence number
411→   * Uses inline protobuf decoder — no external dependencies
412→   */
413→  private parseIpnsRecordBytes(recordBytes: Uint8Array): {
414→    cid: string;
415→    sequenceNumber: string;
416→    signatureV2?: string;
417→    data?: string;
418→    pubKey?: string;
419→  } {
420→    try {
421→      const record = parseIpnsRecord(recordBytes);
422→
423→      // Extract CID from the Value field (format: /ipfs/<cid>)
424→      const valuePath = record.value;
425→      const cidMatch = valuePath.match(/\/ipfs\/([a-zA-Z0-9]+)/);
426→      if (!cidMatch) {
427→        this.logger.error('Failed to extract CID from IPNS record value');
428→        throw new HttpException('Invalid IPNS record format', HttpStatus.BAD_GATEWAY);
429→      }
430→
431→      const cid = cidMatch[1];
432→      const sequenceNumber = String(record.sequence ?? 0n);
433→
434→      // Base64-encode signature fields if present
435→      const signatureV2 = record.signatureV2
436→        ? Buffer.from(record.signatureV2).toString('base64')
437→        : undefined;
438→      const data = record.data ? Buffer.from(record.data).toString('base64') : undefined;
439→      const pubKey = record.pubKey ? Buffer.from(record.pubKey).toString('base64') : undefined;
440→
441→      this.logger.debug(`Parsed IPNS record: cid=${cid}, sequenceNumber=${sequenceNumber}`);
442→      return { cid, sequenceNumber, signatureV2, data, pubKey };
443→    } catch (error) {
444→      if (error instanceof HttpException) {
445→        throw error;
446→      }
447→      this.logger.error(`Failed to parse IPNS record: ${error}`);
448→      throw new HttpException('Invalid IPNS record format', HttpStatus.BAD_GATEWAY);
449→    }
450→  }
451→}
