      const result = await service.lookupUserByPublicKey('0x' + recipientPublicKey);

      expect(result).toBe(true);
      expect(mockUserRepo.findOne).toHaveBeenCalledWith({
        where: { publicKey: recipientPublicKey },
        select: ['id'],
