      await expect(
        service.updateShareEncryptedKey(shareId, recipientId, 'ff'.repeat(64))
      ).rejects.toThrow(ForbiddenException);
      await expect(
        service.updateShareEncryptedKey(shareId, recipientId, 'ff'.repeat(64))
      ).rejects.toThrow('Only the sharer can update share keys');
