  // =========================================================================

  describe('addShareKeys - write-share recipient authorization (M-02)', () => {
    const writeShare: Share = {
      ...mockShare,
      permission: 'write',
      encryptedIpnsKey: Buffer.from('ee'.repeat(64), 'hex'),
    };

    it('should allow write-share recipient to add file keys', async () => {
