import {
  Controller,
  Post,
  Get,
  Delete,
  Body,
  HttpCode,
  HttpStatus,
  UseGuards,
  Request,
  Res,
  Req,
  UnauthorizedException,
  BadRequestException,
} from '@nestjs/common';
import { ApiTags, ApiOperation, ApiResponse, ApiBearerAuth } from '@nestjs/swagger';
import { Response, Request as ExpressRequest } from 'express';
import { AuthService } from './auth.service';
import { AuthMethodService } from './services/auth-method.service';
import { TestAuthService } from './services/test-auth.service';
import { LoginDto, LoginResponseDto } from './dto/login.dto';
import { TokenResponseDto, DesktopRefreshDto, LogoutResponseDto } from './dto/token.dto';
import { TestLoginDto, TestLoginResponseDto } from './dto/test-login.dto';
import {
  LinkMethodDto,
  AuthMethodResponseDto,
  UnlinkMethodDto,
  UnlinkMethodResponseDto,
} from './dto/link-method.dto';
import { DeleteAccountDto, DeleteAccountResponseDto } from './dto/delete-account.dto';
import { Throttle } from '@nestjs/throttler';
import { BypassableThrottlerGuard as ThrottlerGuard } from '../common/guards/throttler-bypass.guard';
import { JwtAuthGuard } from './guards/jwt-auth.guard';
import { User } from './entities/user.entity';
import { MetricsService } from '../metrics/metrics.service';

interface RequestWithUser extends Request {
  user: User;
}

// Cookie configuration
const REFRESH_TOKEN_COOKIE_OPTIONS = {
  httpOnly: true,
  secure: process.env.NODE_ENV === 'production',
  sameSite: 'lax' as const,
  maxAge: 7 * 24 * 60 * 60 * 1000, // 7 days
  path: '/auth', // Only sent to auth endpoints
};

@ApiTags('Auth')
@Controller('auth')
export class AuthController {
  constructor(
    private authService: AuthService,
    private authMethodService: AuthMethodService,
    private testAuthService: TestAuthService,
    private readonly metricsService: MetricsService
  ) {}

  @Post('login')
  @HttpCode(HttpStatus.OK)
  @UseGuards(ThrottlerGuard)
  @Throttle({ default: { limit: 10, ttl: 60000 } })
  @ApiOperation({ summary: 'Authenticate user with Web3Auth ID token' })
  @ApiResponse({
    status: 200,
    description: 'Successfully authenticated',
    type: LoginResponseDto,
  })
  @ApiResponse({ status: 401, description: 'Invalid Web3Auth token' })
  async login(
    @Body() loginDto: LoginDto,
    @Req() req: ExpressRequest,
    @Res({ passthrough: true }) res: Response
  ): Promise<LoginResponseDto> {
    const result = await this.authService.login(loginDto);
    this.metricsService.authLogins.inc({
      method: 'web3auth',
      new_user: String(result.isNewUser),
    });
    const isDesktop = req.headers['x-client-type'] === 'desktop';

    if (isDesktop) {
      // Desktop clients: return refreshToken in response body (no cookie)
      // For scoped temp auth (REQUIRED_SHARE), refreshToken is empty string → omitted
      return {
        accessToken: result.accessToken,
        refreshToken: result.refreshToken || undefined,
        isNewUser: result.isNewUser,
      };
    }

    // Web clients: set refresh token in HTTP-only cookie (skip for scoped temp auth)
    if (result.refreshToken) {
      res.cookie('refresh_token', result.refreshToken, REFRESH_TOKEN_COOKIE_OPTIONS);
    }

    return {
      accessToken: result.accessToken,
      isNewUser: result.isNewUser,
    };
  }

  @Post('refresh')
  @HttpCode(HttpStatus.OK)
  @ApiOperation({ summary: 'Refresh access token using HTTP-only refresh token cookie' })
  @ApiResponse({
    status: 200,
    description: 'Tokens refreshed successfully',
    type: TokenResponseDto,
  })
  @ApiResponse({ status: 401, description: 'Invalid or expired refresh token' })
  async refresh(
    @Req() req: ExpressRequest,
    @Body() body: DesktopRefreshDto,
    @Res({ passthrough: true }) res: Response
  ): Promise<TokenResponseDto> {
    const isDesktop = req.headers['x-client-type'] === 'desktop';

    let refreshToken: string | undefined;

    if (isDesktop) {
      // Desktop clients: read refresh token from request body
      refreshToken = body?.refreshToken;
    } else {
      // Web clients: read refresh token from cookie
      refreshToken = req.cookies?.['refresh_token'];
    }

    if (!refreshToken) {
      throw new UnauthorizedException('No refresh token');
    }

    const result = await this.authService.refreshByToken(refreshToken);

    if (isDesktop) {
      // Desktop clients: return new refreshToken in response body (no cookie)
      return {
        accessToken: result.accessToken,
        refreshToken: result.refreshToken,
        email: result.email,
      };
    }

    // Web clients: set new refresh token in HTTP-only cookie (rotation)
    res.cookie('refresh_token', result.refreshToken, REFRESH_TOKEN_COOKIE_OPTIONS);

    return {
      accessToken: result.accessToken,
      email: result.email,
    };
  }

  @Post('logout')
  @HttpCode(HttpStatus.OK)
  @UseGuards(JwtAuthGuard)
  @ApiBearerAuth()
  @ApiOperation({ summary: 'Logout user and invalidate all refresh tokens' })
  @ApiResponse({
    status: 200,
    description: 'Successfully logged out',
    type: LogoutResponseDto,
  })
  @ApiResponse({ status: 401, description: 'Unauthorized' })
  async logout(
    @Request() req: RequestWithUser,
    @Res({ passthrough: true }) res: Response
  ): Promise<LogoutResponseDto> {
    const isDesktop = (req as unknown as ExpressRequest).headers['x-client-type'] === 'desktop';

    if (!isDesktop) {
      // Web clients: clear the refresh token cookie
      res.clearCookie('refresh_token', { path: '/auth' });
    }

    return this.authService.logout(req.user.id);
  }

  @Delete('account')
  @HttpCode(HttpStatus.OK)
  @UseGuards(ThrottlerGuard)
  @Throttle({ default: { limit: 3, ttl: 60000 } })
  @UseGuards(JwtAuthGuard)
  @ApiBearerAuth()
  @ApiOperation({ summary: 'Permanently delete user account and all associated data' })
  @ApiResponse({
    status: 200,
    description: 'Account deleted successfully',
    type: DeleteAccountResponseDto,
  })
  @ApiResponse({ status: 400, description: 'Invalid confirmation or account not found' })
  @ApiResponse({ status: 401, description: 'Unauthorized' })
  async deleteAccount(
    @Request() req: RequestWithUser,
    @Body() dto: DeleteAccountDto,
    @Res({ passthrough: true }) res: Response
  ): Promise<DeleteAccountResponseDto> {
    if (dto.confirmation !== 'DELETE') {
      throw new BadRequestException('Confirmation must be the string "DELETE"');
    }
    const result = await this.authService.deleteAccount(req.user.id);
    const isDesktop = (req as unknown as ExpressRequest).headers['x-client-type'] === 'desktop';
    if (!isDesktop) {
