import {
  Controller,
  Post,
  Get,
  Delete,
  Body,
  HttpCode,
  HttpStatus,
  UseGuards,
  Res,
  Req,
  UnauthorizedException,
  BadRequestException,
} from '@nestjs/common';
import { ApiTags, ApiOperation, ApiResponse, ApiBearerAuth } from '@nestjs/swagger';
import { Response, Request as ExpressRequest } from 'express';
import { AuthService } from './auth.service';
import { AuthMethodService } from './services/auth-method.service';
import { TestAuthService } from './services/test-auth.service';
import { LoginDto, LoginResponseDto } from './dto/login.dto';
import { TokenResponseDto, DesktopRefreshDto, LogoutResponseDto } from './dto/token.dto';
import { TestLoginDto, TestLoginResponseDto } from './dto/test-login.dto';
import {
  LinkMethodDto,
  AuthMethodResponseDto,
  UnlinkMethodDto,
  UnlinkMethodResponseDto,
} from './dto/link-method.dto';
import { DeleteAccountDto, DeleteAccountResponseDto } from './dto/delete-account.dto';
